select (select count(*) from public.lessons where external_id like 'CKS9-%') as lessons, (select count(*) from public.lesson_specs where lesson like 'CKS9-%') as specs, (select count(*) from public.classes where coalesce(site_slug, follows) like 'cks9-%') as classes, (select count(*) from public.quizzes where title like 'Stage 9 % · Checkpoint-style questions') as question_sets, (select count(*) from public.quizzes where title like 'Stage 9 % · Checkpoint-style examination%') as exams;
