insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('70a67005-2808-5dc0-9ae6-9a95fdf024ac', '85ab2f17-1865-5837-a551-1f5570a233b8', 'short', 'A student tests a variegated leaf (green edges, white centre) for starch. Describe and explain the result.', '[]'::jsonb, 3, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('70a67005-2808-5dc0-9ae6-9a95fdf024ac', 'The green parts turn blue-black and the white centre stays orange-brown [1]; only the green parts made starch [1] because only they contain chlorophyll to absorb light for photosynthesis [1].', 'The green parts turn blue-black and the white centre stays orange-brown [1]; only the green parts made starch [1] because only they contain chlorophyll to absorb light for photosynthesis [1].', '[{"text": "The green parts turn blue-black and the white centre stays orange-brown", "any": ["blue", "black"], "all": [], "marks": 1}, {"text": "Only the green parts made starch", "any": ["green", "edge"], "all": [], "marks": 1}, {"text": "Because only they contain chlorophyll to absorb light for photosynthesis", "any": ["chlorophyll"], "all": [], "marks": 1}]'::jsonb, 'The green parts turn blue-black and the white centre stays orange-brown [1]; only the green parts made starch [1] because only they contain chlorophyll to absorb light for photosynthesis [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
