insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('826830b0-0a20-5ece-b3a7-1c864aedc2ab', '85ab2f17-1865-5837-a551-1f5570a233b8', 'short', 'Explain why the rate of photosynthesis of a plant in a greenhouse falls at night.', '[]'::jsonb, 2, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('826830b0-0a20-5ece-b3a7-1c864aedc2ab', 'At night there is no light [1], so light becomes the limiting factor and photosynthesis stops because light energy is needed [1].', 'At night there is no light [1], so light becomes the limiting factor and photosynthesis stops because light energy is needed [1].', '[{"text": "At night there is no light", "any": ["no light", "dark", "less light"], "all": [], "marks": 1}, {"text": "Light becomes the limiting factor and photosynthesis stops because light energy is needed", "any": ["limiting", "light energy", "cannot photosynthesise", "slower"], "all": [], "marks": 1}]'::jsonb, 'At night there is no light [1], so light becomes the limiting factor and photosynthesis stops because light energy is needed [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
