insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('c7e03ac9-17b3-5131-9f9a-daae8b891fe9', 'be6d0531-b087-58c0-b312-a740bbf35e8b', 'short', 'Explain why two sisters with the same parents do not look exactly the same.', '[]'::jsonb, 2, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c7e03ac9-17b3-5131-9f9a-daae8b891fe9', 'Each sister came from a different sperm and egg [1], and each gamete carries a different mixture of the parents'' chromosomes, so each has a new combination of DNA (genes) [1].', 'Each sister came from a different sperm and egg [1], and each gamete carries a different mixture of the parents'' chromosomes, so each has a new combination of DNA (genes) [1].', '[{"text": "Each sister came from a different sperm and egg", "any": ["different", "new combination", "mixture"], "all": [], "marks": 1}, {"text": "Each gamete carries a different mixture of the parents'' chromosomes, so each has a new combination of DNA (genes)", "any": ["gamete", "sperm", "egg", "chromosomes from each parent"], "all": [], "marks": 1}]'::jsonb, 'Each sister came from a different sperm and egg [1], and each gamete carries a different mixture of the parents'' chromosomes, so each has a new combination of DNA (genes) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
