insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('916784f7-f151-5bbc-aae3-dcacff57a9cd', '45723a83-feb8-53e3-8f3c-ed29e3ba943c', 'Unit 5 Variation and natural selection: How populations change over time', 'Stage 9 Biology · Objectives 9Bp.03, 9Bp.04', '/cks9-bio-5/', 'CKS9-BIO-L5', 23, 60, 50) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-BIO-L5', 'Unit 5 Variation and natural selection: How populations change over time', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Genes", "Environment", "Both", "Genes", "Environment"], "tip": "Could you change it in your life?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Continuous", "Discontinuous", "Continuous", "Discontinuous"], "tip": "Any value, or set groups?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["continuous"], ["histogram"], ["range", "any value", "measured"]], "tips": ["Can hand span be any value?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["3rd", "1st", "4th", "2nd"], "tip": "Vary, compete, survive, pass on."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 4, "pts": [["dark", "black"], ["camouflage", "hidden", "less visible", "not seen"], ["eaten", "bird", "predator"], ["reproduce", "breed", "pass on", "offspring"]], "tips": ["Use the four steps."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["resistant", "some bacteria survive", "varia"], ["killed", "not resistant die", "susceptible"], ["reproduce", "multiply", "divide", "pass on", "spread"]], "tips": ["Which bacteria are left?"]}]}, "models": {"1": [["Q1", "Blood group and eye colour: genes. Scar and language: environment. Height: both (genes and diet)."]], "2": [["Q2", "Height and mass can take any value (continuous); blood group and tongue rolling have set groups (discontinuous)."], ["Q3", "It is continuous variation [1], so they should draw a histogram (with grouped classes) [1] because hand span can take any value within a range [1]."]], "3": [["Q4", "Variation → competition → survival of the best adapted → reproduction and passing on genes."]], "4": [["Q5", "On soot-blackened trees the dark moths were better camouflaged [1] so birds could not see them easily [1], while pale moths were eaten [1]; more dark moths survived to reproduce and passed on the gene for dark colour, so they became more common [1]."]], "5": [["Q6", "Some bacteria vary and are more resistant to the antibiotic [1]; the antibiotic kills the non-resistant ones first, and stopping early leaves the resistant ones alive [1]; these multiply and pass on resistance, so the population becomes resistant [1]."]], "6": [["Exit ticket", "Variation; competition; survival of the best adapted; reproduction passing on genes."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Genes, environment or both?", "Q2": "Which type?", "Q3": "Students measured the hand span of 30 classmates. Name the type of variation and the type of graph they should draw. Explain your choice.", "Q4": "Put the steps of natural selection in order.", "Q5": "Explain how the number of dark peppered moths increased in polluted areas.", "Q6": "A patient stops taking antibiotics after two days instead of finishing the course. Use natural selection to explain how this can lead to antibiotic-resistant bacteria."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
