insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('b55968ca-8982-5557-984c-bb2641209c38', '45723a83-feb8-53e3-8f3c-ed29e3ba943c', 'short', 'Giraffes with longer necks can reach more leaves. Explain, using natural selection, why giraffes today have long necks.', '[]'::jsonb, 4, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b55968ca-8982-5557-984c-bb2641209c38', 'Giraffes varied in neck length [1]; in competition for food, those with longer necks could reach more leaves [1] and were more likely to survive [1]; they reproduced and passed on the genes for long necks, so over many generations necks became longer [1].', 'Giraffes varied in neck length [1]; in competition for food, those with longer necks could reach more leaves [1] and were more likely to survive [1]; they reproduced and passed on the genes for long necks, so over many generations necks became longer [1].', '[{"text": "Giraffes varied in neck length", "any": ["vari", "some had longer", "differ"], "all": [], "marks": 1}, {"text": "In competition for food, those with longer necks could reach more leaves", "any": ["compet", "food", "leaves", "reach"], "all": [], "marks": 1}, {"text": "Were more likely to survive", "any": ["surviv"], "all": [], "marks": 1}, {"text": "They reproduced and passed on the genes for long necks, so over many generations necks became longer", "any": ["pass on", "reproduce", "offspring", "genes"], "all": [], "marks": 1}]'::jsonb, 'Giraffes varied in neck length [1]; in competition for food, those with longer necks could reach more leaves [1] and were more likely to survive [1]; they reproduced and passed on the genes for long necks, so over many generations necks became longer [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
