insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-BIO-L7', 'Unit 7 Populations, the carbon cycle and climate change: Carbon on the move', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Removes CO₂", "Adds CO₂", "Adds CO₂", "Moves carbon between organisms", "Adds CO₂"], "tip": "Only one process removes it."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["photosynthesis", "fewer trees", "less carbon dioxide taken"], ["burn", "combustion", "decompos", "respir"]], "tips": ["Two effects."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["105", "100", "105 ppm"], ["fossil fuel", "burning", "combustion", "deforestation"]], "tips": ["Subtract, then why."]}, {"kind": "choice", "id": "q3_1", "q": "Q4", "max": 3, "n": 3, "ans": ["Supported", "Supported", "Not supported"], "tip": "Read the numbers."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["grass", "plant", "food"], ["water", "drink"], ["die", "starv", "fewer young", "breed less", "migrat"]], "tips": ["Producers first."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["carbon dioxide"], ["warm", "temperature", "greenhouse"], ["sea level", "melt", "ice", "expand"], ["flood", "habitat", "lost", "destroyed"]], "tips": ["Link: CO₂ → warming → sea level → habitat."]}]}, "models": {"1": [["Q1", "Only photosynthesis removes carbon dioxide; respiration, decomposition and combustion add it; feeding moves carbon along food chains."]], "2": [["Q2", "Fewer trees means less carbon dioxide is removed by photosynthesis [1], and burning or decomposing the trees releases carbon dioxide [1]."]], "3": [["Q3", "420 − 315 = 105 ppm [1]; mainly caused by burning fossil fuels (and deforestation) [1]."], ["Q4", "Both carbon dioxide and temperature have increased."]], "4": [["Q5", "Less rain means less grass and other plants grow [1], so there is less food and less water for the antelope [1]; more die of starvation or thirst and fewer young are born, so the population decreases [1]."]], "5": [["Q6", "Burning fossil fuels releases carbon dioxide [1], a greenhouse gas that traps heat and raises global temperature [1]; ice melts and sea water expands, so sea levels rise [1]; the island floods and the species loses its only habitat, so every individual dies and it becomes extinct [1]."]], "6": [["Exit ticket", "Removes: photosynthesis. Adds: respiration, decomposition or combustion."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Does the process add or remove carbon dioxide from the air?", "Q2": "Explain how deforestation increases the amount of carbon dioxide in the air.", "Q3": "Use the figures to calculate the increase in carbon dioxide since 1958 and suggest the main cause.", "Q4": "What does the evidence show?", "Q5": "Explain how a long drought could cause the population of a species of antelope to decrease.", "Q6": "Explain how burning fossil fuels could lead to the extinction of a species that lives only on a low-lying island."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
