insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('576ac633-914c-5de1-9d99-dbe65a8377ec', 'cf69cc81-1cd7-5fad-99f2-05fe164e428c', 'Unit 1 The Periodic Table and Group 1: Patterns in the Periodic Table', 'Stage 9 Chemistry · Objectives 9Cm.01, 9Cp.01', '/cks9-chem-1/', 'CKS9-CHEM-L1', 23, 60, 10) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-CHEM-L1', 'Unit 1 The Periodic Table and Group 1: Patterns in the Periodic Table', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Group 1", "Group 7", "Group 0", "Period"], "tip": "Columns are groups."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Group 1, Period 3", "Group 7, Period 2", "Group 2, Period 3", "Group 0, Period 2"], "tip": "Last number = group; how many numbers = period."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["one outer", "1 outer", "one electron in", "same number of outer"], ["similar", "same", "react"]], "tips": ["Count the outer electrons."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 3, "n": 3, "ans": ["Decreases", "Increases", "Increases"], "tip": "Read down the column."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["potassium hydroxide+hydrogen"], ["float", "fizz", "bubble", "move"], ["lilac", "flame", "melt", "ignite", "catches fire"]], "tips": ["Equation + what you see."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["more shells", "larger atom", "further"], ["less", "weaker", "attract"], ["lose", "lost", "given away"]], "tips": ["Shells → attraction → losing."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["lower", "below 63", "less than 63"], ["more vigorous", "violent", "explo", "faster", "more reactive"], ["rubidium hydroxide"], ["hydrogen"]], "tips": ["Follow the trend."]}]}, "models": {"1": [["Q1", "Alkali metals: Group 1. Halogens: Group 7. Noble gases: Group 0. A row is a period."]], "2": [["Q2", "2,8,1: one outer electron, three shells. 2,7: Group 7, two shells. 2,8,2: Group 2, three shells. 2,8: full outer shell, Group 0."], ["Q3", "Both have one electron in their outer shell [1], so they have similar chemical properties and react in the same way [1]."]], "3": [["Q4", "Melting point decreases from 181 to 63 °C; reactivity and the speed of reaction with water increase."], ["Q5", "Potassium + water → potassium hydroxide + hydrogen [1]; it floats and fizzes, moving quickly on the surface [1]; it melts and the hydrogen ignites with a lilac flame [1]."]], "4": [["Q6", "Potassium has more electron shells, so its outer electron is further from the nucleus [1]; the attraction between the nucleus and this electron is weaker [1], so the electron is lost more easily in a reaction [1]."]], "5": [["Q7", "Its melting point will be lower than 63 °C (about 39 °C) [1]; it reacts even more violently with water, possibly explosively [1], making rubidium hydroxide [1] and hydrogen gas [1]."]], "6": [["Exit ticket", "Reactivity increases going down the group."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which part of the table?", "Q2": "Electron arrangement → position", "Q3": "Explain why sodium and potassium are in the same group.", "Q4": "Use the data to spot the trend. Melting points: lithium 181 °C, sodium 98 °C, potassium 63 °C.", "Q5": "Write the word equation for potassium reacting with water and describe two observations.", "Q6": "Explain why potassium is more reactive than lithium.", "Q7": "Rubidium is below potassium in Group 1. Predict its melting point compared with potassium (63 °C), how it reacts with water, and the products."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
