insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('59544df1-9081-5542-8481-df05b1a31e8b', 'dd6e736b-a550-5640-a94c-c012f971a2f8', 'Unit 2 Covalent and ionic bonding: How atoms join: covalent and ionic bonds', 'Stage 9 Chemistry · Objectives 9Cm.02, 9Cm.03, 9Cm.04, 9Cm.05, 9Cp.04', '/cks9-chem-2/', 'CKS9-CHEM-L2', 29, 60, 20) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-CHEM-L2', 'Unit 2 Covalent and ionic bonding: How atoms join: covalent and ionic bonds', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Covalent", "Ionic", "Covalent", "Ionic", "Covalent"], "tip": "Metal involved?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["1", "2", "4", "1"], "tip": "Count the shared pairs."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["share", "shared"], ["pair", "two electrons", "2 electrons"]], "tips": ["Share what?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Na⁺", "Cl⁻", "Mg²⁺", "O²⁻"], "tip": "Lose = positive; gain = negative."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["sodium+lose", "transfer"], ["chlorine+gain"], ["attract", "opposite"]], "tips": ["Who gives, who takes, what holds them?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["Simple molecular", "Giant ionic", "Giant covalent", "Simple molecular"], "tip": "Low m.p. → molecules."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["molecule", "simple"], ["weak", "between molecules", "intermolecular"], ["ionic", "lattice", "giant", "strong"]], "tips": ["Weak forces or strong bonds to break?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["x+giant covalent", "x is giant covalent"], ["no ions", "not conduct", "does not conduct", "no charged particles"], ["y+ionic", "y is ionic", "y is giant ionic"], ["molten", "ions move", "ions can move", "free to move"]], "tips": ["Melting point + conduction."]}]}, "models": {"1": [["Q1", "Non-metals only: covalent. Metal with non-metal: ionic."]], "2": [["Q2", "H₂ one; H₂O two; CH₄ four; HCl one."], ["Q3", "A covalent bond is a shared [1] pair of electrons between two atoms [1]."]], "3": [["Q4", "Na⁺, Cl⁻, Mg²⁺, O²⁻."], ["Q5", "Each sodium atom loses one electron to become Na⁺ [1]; each chlorine atom gains that electron to become Cl⁻ [1]; the oppositely charged ions attract each other strongly (ionic bond) [1]."]], "4": [["Q6", "Low melting point: simple molecular. High, conducts when molten: ionic. Very high, very hard: giant covalent."], ["Q7", "Water is made of small molecules [1] held together by weak forces between the molecules, which need little energy to overcome [1]; sodium chloride is a giant ionic lattice with strong attractions between ions that need much more energy to break [1]."]], "5": [["Q8", "X is giant covalent [1]: its very high melting point shows strong bonds throughout, and it does not conduct because it has no ions or free electrons [1]; Y is giant ionic [1]: it conducts only when molten because the ions are then free to move [1]."]], "6": [["Exit ticket", "A shared pair of electrons between two atoms."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Covalent or ionic?", "Q2": "How many covalent bonds (shared pairs)?", "Q3": "Describe what a covalent bond is and draw a dot-and-cross diagram of a hydrogen molecule in your book.", "Q4": "What ion forms?", "Q5": "Describe how sodium and chlorine atoms form sodium chloride.", "Q6": "Which structure fits?", "Q7": "Explain why water has a much lower melting point than sodium chloride.", "Q8": "Substance X melts at 1600 °C, does not dissolve in water and does not conduct electricity, even when molten. Substance Y melts at 714 °C and conducts only when molten. Identify the structure of each and give reasons."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
