insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('f5839832-c19a-5b9d-b24a-c1f9c5813903', 'dd6e736b-a550-5640-a94c-c012f971a2f8', 'short', 'A magnesium atom has the electron arrangement 2,8,2. Describe what happens when it forms an ion and give the charge on the ion.', '[]'::jsonb, 2, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f5839832-c19a-5b9d-b24a-c1f9c5813903', 'It loses its two outer electrons [1] to form an ion with a 2+ charge (Mg²⁺) [1].', 'It loses its two outer electrons [1] to form an ion with a 2+ charge (Mg²⁺) [1].', '[{"text": "It loses its two outer electrons", "any": ["loses two", "lose two", "loses 2", "lose 2"], "all": [], "marks": 1}, {"text": "To form an ion with a 2+ charge (Mg²⁺)", "any": ["mg²⁺"], "all": [], "marks": 1}]'::jsonb, 'It loses its two outer electrons [1] to form an ion with a 2+ charge (Mg²⁺) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
