insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('46a4fda3-2554-58ef-aa3c-e0f2867bed2d', 'dd6e736b-a550-5640-a94c-c012f971a2f8', 'short', 'Methane boils at −162 °C. Explain why methane is a gas at room temperature even though its covalent bonds are strong.', '[]'::jsonb, 2, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('46a4fda3-2554-58ef-aa3c-e0f2867bed2d', 'Only the forces between the methane molecules have to be overcome to boil it [1], and these forces are weak, needing very little energy [1].', 'Only the forces between the methane molecules have to be overcome to boil it [1], and these forces are weak, needing very little energy [1].', '[{"text": "Only the forces between the methane molecules have to be overcome to boil it", "any": ["between molecules", "intermolecular"], "all": [], "marks": 1}, {"text": "These forces are weak, needing very little energy", "any": ["weak", "little energy"], "all": [], "marks": 1}]'::jsonb, 'Only the forces between the methane molecules have to be overcome to boil it [1], and these forces are weak, needing very little energy [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
