insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0dfa4576-0b21-5f8b-ac76-bde1c7b094db', 'In the solid the ions are held in fixed positions and cannot move [1]; when molten the ions are free to move and carry charge [1].', 'In the solid the ions are held in fixed positions and cannot move [1]; when molten the ions are free to move and carry charge [1].', '[{"text": "In the solid the ions are held in fixed positions and cannot move", "any": ["cannot move", "not free"], "all": [], "marks": 1}, {"text": "When molten the ions are free to move and carry charge", "any": ["free to move", "ions move"], "all": [], "marks": 1}]'::jsonb, 'In the solid the ions are held in fixed positions and cannot move [1]; when molten the ions are free to move and carry charge [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
