insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('f58e702c-fc4e-5adb-a0bc-54c6fc192d03', '932f61e7-31f8-58d0-a814-363395a1a4fb', 'Unit 3 Density: Mass, volume and density', 'Stage 9 Chemistry · Objectives 9Cp.02, 9Cp.03', '/cks9-chem-3/', 'CKS9-CHEM-L3', 24, 60, 30) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-CHEM-L3', 'Unit 3 Density: Mass, volume and density', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["2.0 g/cm³", "0.5 g/cm³", "8.0 g/cm³", "1.0 g/cm³"], "tip": "Mass ÷ volume."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["12"], ["30 ÷ 12", "30/12", "30 / 12", "mass ÷ volume", "mass/volume"], ["2.5"]], "tips": ["Volume first."]}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 4, "n": 4, "ans": ["Ruler: l × w × h", "Displacement", "Measuring cylinder only", "Displacement"], "tip": "Regular, irregular or liquid?"}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["193 g", "10 cm³", "27 g", "2 cm³"], "tip": "Choose the arrangement first."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["11.6", "11.58"], ["less", "lower", "not 19.3", "different"], ["not pure", "fake", "not gold", "not real"]], "tips": ["Calculate, compare, conclude."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["far apart", "spread out", "large spaces", "gaps"], ["same mass", "fewer particles", "larger volume", "more space"]], "tips": ["Particles in a given volume."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["balance", "scale"], ["measuring cylinder"], ["subtract", "empty", "difference"], ["divide", "mass ÷ volume", "mass/volume", "repeat"]], "tips": ["Mass, volume, then divide."]}]}, "models": {"1": [["Q1", "40÷20=2.0; 15÷30=0.5; 80÷10=8.0; 50÷50=1.0 g/cm³."]], "2": [["Q2", "Volume = 62 − 50 = 12 cm³ [1]; density = mass ÷ volume = 30 ÷ 12 [1] = 2.5 g/cm³ [1]."], ["Q3", "Regular: ruler. Irregular: displacement. Liquid: measuring cylinder."]], "3": [["Q4", "m = 19.3 × 10 = 193 g; V = 27 ÷ 2.7 = 10 cm³; m = 2.7 × 10 = 27 g; V = 2 ÷ 1 = 2 cm³."], ["Q5", "Density = 579 ÷ 50 = 11.6 g/cm³ [1]; this is less than 19.3 g/cm³ [1], so the bar is not pure gold [1]."]], "4": [["Q6", "In steam the particles are much further apart than in liquid water [1], so a given volume contains far fewer particles and much less mass [1]."]], "5": [["Q7", "Find the mass of an empty measuring cylinder on a balance [1]; pour in oil and read the volume at eye level, e.g. 50 cm³ [1]; find the mass again and subtract the empty mass to get the mass of oil [1]; density = mass ÷ volume; repeat and take a mean [1]."]], "6": [["Exit ticket", "density = mass ÷ volume; g/cm³."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Calculate the density.", "Q2": "A stone is lowered into a measuring cylinder. The water level rises from 50 cm³ to 62 cm³. The stone has a mass of 30 g. Calculate its density.", "Q3": "Which method gives the volume?", "Q4": "Calculate.", "Q5": "A \"gold\" bar has a mass of 579 g and a volume of 50 cm³. Gold has a density of 19.3 g/cm³. Show whether the bar is pure gold.", "Q6": "Use the particle model to explain why the density of steam is much lower than the density of water.", "Q7": "Plan how to find the density of a cooking oil as accurately as possible. Give the equipment, the measurements and the calculation."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
