insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('165d6203-e04d-5cc2-aa69-b27789a49301', 'Put water in a measuring cylinder and record the level, then lower in the stone [1]; the rise in water level (difference between the readings) is the volume of the stone [1].', 'Put water in a measuring cylinder and record the level, then lower in the stone [1]; the rise in water level (difference between the readings) is the volume of the stone [1].', '[{"text": "Put water in a measuring cylinder and record the level, then lower in the stone", "any": ["water", "measuring cylinder", "eureka"], "all": [], "marks": 1}, {"text": "The rise in water level (difference between the readings) is the volume of the stone", "any": ["rise", "difference", "displaced", "subtract"], "all": [], "marks": 1}]'::jsonb, 'Put water in a measuring cylinder and record the level, then lower in the stone [1]; the rise in water level (difference between the readings) is the volume of the stone [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
