insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('835379b6-bd4f-5e89-819a-e4932f91651d', '12a0b320-d874-56c4-9dae-e2bbdd36cf89', 'Unit 4 Equations and conservation: Writing equations: nothing is lost', 'Stage 9 Chemistry · Objectives 9Cc.01, 9Cc.05', '/cks9-chem-4/', 'CKS9-CHEM-L4', 25, 60, 40) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-CHEM-L4', 'Unit 4 Equations and conservation: Writing equations: nothing is lost', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Reactant", "Product", "Product", "Reactant"], "tip": "Left of the arrow or right?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 5, "n": 5, "ans": ["H₂O", "CO₂", "NaCl", "MgO", "O₂"], "tip": "Count the atoms."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["carbon+oxygen+carbon dioxide"], ["c + o2", "c+o2", "c + o₂", "co2", "co₂"]], "tips": ["Words, then symbols."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Increases", "Decreases", "Stays the same", "Increases"], "tip": "Gas in, gas out, or sealed?"}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["1.6"], ["oxygen", "from the air"], ["combine", "join", "react", "conserved", "atoms"]], "tips": ["Subtract; then why."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 4, "n": 4, "ans": ["Exothermic", "Endothermic", "Exothermic", "Endothermic"], "tip": "Hotter or colder?"}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["hydrogen", "gas"], ["escape", "lost", "leaves", "into the air"], ["seal", "closed", "balloon", "stopper", "bung"]], "tips": ["What is made, where does it go?"]}]}, "models": {"1": [["Q1", "Left of the arrow: reactants. Right: products."], ["Q2", "Into the air as carbon dioxide and water vapour (gases we cannot see)."]], "2": [["Q3", "H₂O, CO₂, NaCl, MgO, O₂."], ["Q4", "carbon + oxygen → carbon dioxide [1]; C + O₂ → CO₂ [1]."]], "3": [["Q5", "Gaining oxygen: increases. Losing CO₂: decreases. Sealed: the same."], ["Q6", "Mass of oxygen = 4.0 − 2.4 = 1.6 g [1]; the mass increased because oxygen from the air [1] combined with the magnesium; no mass was created, the atoms of oxygen were added [1]."]], "4": [["Q7", "Gets hotter: exothermic. Gets colder: endothermic."]], "5": [["Q8", "The reaction makes hydrogen gas [1], which escapes into the air, so the mass on the balance falls by 0.4 g [1]; doing the reaction in a sealed flask (or with a balloon over the top) would keep the gas in and the mass would stay the same [1]."]], "6": [["Exit ticket", "It stays the same: mass is conserved."]]}, "labels": {"q1_1": "Q2", "q2_1": "Q4", "q3_1": "Q6", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Reactant or product?", "Q2": "A burning candle seems to get lighter. Suggest where the mass goes.", "Q3": "Name or formula?", "Q4": "Write the word equation and the symbol equation for carbon burning in oxygen to make carbon dioxide.", "Q5": "What happens to the mass on the balance?", "Q6": "When 2.4 g of magnesium is burned, 4.0 g of magnesium oxide forms. Calculate the mass of oxygen that reacted and explain why the mass increased.", "Q7": "Exothermic or endothermic?", "Q8": "A student adds zinc to hydrochloric acid in an open beaker on a balance. The reading falls from 150.0 g to 149.6 g. Explain this result and suggest how to show that mass is conserved."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
