insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('ceb69cb6-9265-5d86-8e42-a43ef684fc68', '12a0b320-d874-56c4-9dae-e2bbdd36cf89', 'short', 'When calcium carbonate is heated in an open tube its mass decreases. Explain why, using the word equation calcium carbonate → calcium oxide + carbon dioxide.', '[]'::jsonb, 2, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
