insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-CHEM-L5', 'Unit 5 Displacement reactions: The reactivity series and displacement', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["More reactive", "Less reactive", "More reactive", "Less reactive"], "tip": "Above or below iron in the series?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Reaction", "No reaction", "Reaction", "No reaction", "No reaction"], "tip": "Is the added metal higher?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["brown", "pink", "copper", "coating"], ["blue", "colourless", "fade", "warm", "hot"]], "tips": ["Colours and temperature."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["zinc sulfate"], ["copper"]], "tips": ["Swap partners."]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["no reaction", "nothing", "no change"], ["less reactive", "lower"]], "tips": ["Where is copper in the series?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 3, "n": 3, "ans": ["Most reactive", "Middle", "Least reactive"], "tip": "Count the displacements."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["aluminium oxide+iron"], ["more reactive", "higher"], ["weld", "railway", "track", "rail"]], "tips": ["Products, reason, use."]}]}, "models": {"1": [["Q1", "Magnesium and zinc are above iron; copper and silver are below."]], "2": [["Q2", "A reaction happens only if the added metal is more reactive than the metal in the salt."], ["Q3", "A pink-brown solid (copper) forms on the magnesium [1]; the blue colour fades and the mixture gets warm [1]."]], "3": [["Q4", "zinc sulfate [1] + copper [1]."], ["Q5", "There is no reaction [1] because copper is less reactive than iron, so it cannot displace iron [1]."]], "4": [["Q6", "P displaces two (most reactive), R displaces one, Q none (least reactive)."]], "5": [["Q7", "aluminium + iron oxide → aluminium oxide + iron [1]; it happens because aluminium is more reactive than iron [1]; the molten iron made is used to weld railway tracks [1]."]], "6": [["Exit ticket", "No: zinc is less reactive than magnesium."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q3_1": "Q5", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "More or less reactive than iron?", "Q2": "Will a reaction happen?", "Q3": "Describe two observations when magnesium ribbon is placed in blue copper sulfate solution.", "Q4": "Complete the word equation: zinc + copper sulfate → ______ + ______", "Q5": "A student puts copper into iron sulfate solution. Predict what happens and explain why.", "Q6": "Results: P displaces Q and R. Q displaces nothing. R displaces Q. Put the metals in order.", "Q7": "Aluminium powder is heated with iron oxide. Write the word equation, explain why the reaction happens and give one use."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
