insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('a2b83ab2-4837-508a-80c2-5272f1270af1', '5b40ee0f-8f6a-5ad5-bf59-55a3538e7dcd', 'short', 'An iron nail is left in blue copper sulfate solution. Describe two changes you would see and explain why they happen.', '[]'::jsonb, 3, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a2b83ab2-4837-508a-80c2-5272f1270af1', 'A pink-brown coating of copper forms on the nail [1]; the blue solution becomes paler or green [1], because iron is more reactive than copper and displaces it from the solution [1].', 'A pink-brown coating of copper forms on the nail [1]; the blue solution becomes paler or green [1], because iron is more reactive than copper and displaces it from the solution [1].', '[{"text": "A pink-brown coating of copper forms on the nail", "any": ["brown", "pink", "copper"], "all": [], "marks": 1}, {"text": "The blue solution becomes paler or green", "any": ["blue", "green", "fade", "paler"], "all": [], "marks": 1}, {"text": "Because iron is more reactive than copper and displaces it from the solution", "any": ["more reactive", "displace"], "all": [], "marks": 1}]'::jsonb, 'A pink-brown coating of copper forms on the nail [1]; the blue solution becomes paler or green [1], because iron is more reactive than copper and displaces it from the solution [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
