insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('e960b73f-b8ac-5dfb-a9f6-02922d18436a', '5b40ee0f-8f6a-5ad5-bf59-55a3538e7dcd', 'short', 'Metal W displaces copper but not zinc. Place W in the reactivity series and suggest which metal it could be.', '[]'::jsonb, 2, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e960b73f-b8ac-5dfb-a9f6-02922d18436a', 'W is between zinc and copper [1]; it could be iron [1].', 'W is between zinc and copper [1]; it could be iron [1].', '[{"text": "W is between zinc and copper", "any": ["between zinc and copper", "below zinc", "above copper"], "all": [], "marks": 1}, {"text": "It could be iron", "any": ["iron", "lead", "tin"], "all": [], "marks": 1}]'::jsonb, 'W is between zinc and copper [1]; it could be iron [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
