insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-CHEM-L6', 'Unit 6 Making and purifying salts: From acid to crystals', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["magnesium chloride", "zinc sulfate", "copper nitrate", "calcium chloride"], "tip": "Metal first, acid second."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["magnesium chloride"], ["hydrogen"], ["pop", "squeaky"]], "tips": ["Salt + gas; test."]}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["calcium chloride"], ["water+carbon dioxide"]], "tips": ["Three products."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Uses up all the acid", "Removes unreacted solid", "Makes the solution concentrated", "Lets crystals form slowly"], "tip": "Purpose of each step."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["all the acid", "no acid left", "used up", "react"], ["pure", "not contaminated", "only salt"]], "tips": ["What would be left otherwise?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["excess", "until no more fizz", "until fizzing stops"], ["filter"], ["evaporat", "heat"], ["cool", "crystal", "dry"]], "tips": ["Excess, filter, evaporate, crystallise."]}]}, "models": {"1": [["Q1", "Magnesium chloride; zinc sulfate; copper nitrate; calcium chloride."]], "2": [["Q2", "magnesium + hydrochloric acid → magnesium chloride [1] + hydrogen [1]; a lighted splint gives a squeaky pop [1]."], ["Q3", "calcium carbonate + hydrochloric acid → calcium chloride [1] + water + carbon dioxide [1]."]], "3": [["Q4", "Excess uses up the acid; filtering removes excess solid; evaporating concentrates; cooling forms crystals."]], "4": [["Q5", "Excess makes sure all the sulfuric acid reacts and is used up [1], so the copper sulfate made is pure and not mixed with acid [1]."]], "5": [["Q6", "Add zinc to warm sulfuric acid until it is in excess and fizzing stops [1]; filter off the unreacted zinc [1]; heat the filtrate to evaporate some of the water [1]; leave it to cool so crystals form, then filter and dry them between filter papers [1]."]], "6": [["Exit ticket", "Zinc chloride."]]}, "labels": {"q2_0": "Q2", "q2_1": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Name the salt.", "Q2": "Write the word equation for magnesium reacting with hydrochloric acid and describe the test for the gas made.", "Q3": "Write the word equation for calcium carbonate reacting with hydrochloric acid.", "Q4": "Why is each step done?", "Q5": "Explain why copper carbonate is added in excess when making copper sulfate.", "Q6": "Describe how to make pure, dry crystals of zinc sulfate from zinc and dilute sulfuric acid."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
