insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('05a315d1-25b6-5431-8ef8-20950e511e48', 'Add excess copper carbonate to the acid [1]; filter, heat to evaporate some water, then leave to cool [1]; filtering removes the unreacted (excess) copper carbonate [1].', 'Add excess copper carbonate to the acid [1]; filter, heat to evaporate some water, then leave to cool [1]; filtering removes the unreacted (excess) copper carbonate [1].', '[{"text": "Add excess copper carbonate to the acid", "any": ["add excess", "excess first", "copper carbonate first"], "all": [], "marks": 1}, {"text": "Filter, heat to evaporate some water, then leave to cool", "any": ["filter then heat", "filter, heat"], "all": [], "marks": 1}, {"text": "Filtering removes the unreacted (excess) copper carbonate", "any": ["remove", "unreacted", "excess"], "all": [], "marks": 1}]'::jsonb, 'Add excess copper carbonate to the acid [1]; filter, heat to evaporate some water, then leave to cool [1]; filtering removes the unreacted (excess) copper carbonate [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
