insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('2c1b167f-c448-54ec-9220-2320adc57a12', 'aebe42ae-b8a9-5c8b-958c-2354340c2275', 'Unit 7 Rates of reaction: Speeding up reactions', 'Stage 9 Chemistry · Objectives 9Cc.04', '/cks9-chem-7/', 'CKS9-CHEM-L7', 20, 60, 70) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-CHEM-L7', 'Unit 7 Rates of reaction: Speeding up reactions', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Faster", "Slower", "Faster", "Slower"], "tip": "More collisions = faster."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 4, "pts": [["concentration"], ["volume of gas", "gas", "mass", "time"], ["temperature", "volume of acid", "size", "surface area", "mass of marble"], ["temperature", "volume of acid", "size", "surface area", "mass of marble", "same"]], "tips": ["Change, measure, keep."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["2.5"], ["surface area", "smaller pieces", "more exposed"], ["collision", "collide", "more particles"]], "tips": ["Rate = volume ÷ time, then why."]}, {"kind": "choice", "id": "q3_1", "q": "Q4", "max": 3, "n": 3, "ans": ["Steepest at the start", "Levels off", "Same final volume"], "tip": "Steep = fast."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["faster", "more energy", "move faster"], ["more often", "more frequent", "more collisions"], ["enough energy", "successful", "energy to react"]], "tips": ["Two reasons."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["surface area"], ["oxygen", "air", "collide"], ["fast", "rapid", "quick", "explo"]], "tips": ["Spread out vs piled up."]}]}, "models": {"1": [["Q1", "More concentrated, powdered or hotter: faster. Large lumps or cold: slower."]], "2": [["Q2", "Independent: the concentration of the acid [1]; dependent: the volume of gas made in a set time (or mass lost) [1]; controls: temperature [1] and the mass and size of marble chips (and volume of acid) [1]."]], "3": [["Q3", "Rate = 50 ÷ 20 = 2.5 cm³/s [1]; the powder has a larger surface area [1], so more acid particles can collide with the carbonate each second, giving a faster rate [1]."], ["Q4", "Fastest at the start; levels off when a reactant runs out; same final volume."]], "4": [["Q5", "At a higher temperature the particles move faster [1], so they collide more often [1] and more of the collisions have enough energy to react [1]."]], "5": [["Q6", "Fine dust in the air has a huge surface area [1], so oxygen particles can collide with a very large number of flour particles at once [1]; the reaction is so fast that it is explosive, while in a pile only the surface can react [1]."]], "6": [["Exit ticket", "Higher concentration, larger surface area (smaller pieces), higher temperature (or a catalyst)."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Faster or slower?", "Q2": "Name the independent variable, the dependent variable and two control variables in an experiment to find how acid concentration affects the rate of reaction with marble chips.", "Q3": "In 20 s, 50 cm³ of gas is collected with powder but 20 cm³ with large chips. Calculate the rate with the powder and explain the difference.", "Q4": "Read the graph.", "Q5": "Use particles to explain why a reaction is faster at a higher temperature.", "Q6": "Explain why fine flour dust in a mill can explode, but a pile of flour burns only slowly."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
