insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('59912102-493e-57f4-918e-d6f96c1cbf33', 'There are more acid particles in the same volume [1], so collisions with the other reactant happen more often [1].', 'There are more acid particles in the same volume [1], so collisions with the other reactant happen more often [1].', '[{"text": "There are more acid particles in the same volume", "any": ["more particles", "more acid particles"], "all": [], "marks": 1}, {"text": "Collisions with the other reactant happen more often", "any": ["collisions", "collide"], "all": [], "marks": 1}]'::jsonb, 'There are more acid particles in the same volume [1], so collisions with the other reactant happen more often [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
