insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('7d8f5d79-e1e0-55a3-94fd-5efccd4404e8', 'f5b136b0-fa9a-5352-9b07-e792a03aefd0', 'Unit 8 Plate tectonics (Earth and Space): Moving plates and the evidence for them', 'Stage 9 Chemistry · Objectives 9ESp.01, 9ESp.02', '/cks9-chem-8/', 'CKS9-CHEM-L8', 22, 60, 80) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-CHEM-L8', 'Unit 8 Plate tectonics (Earth and Space): Moving plates and the evidence for them', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Crust", "Mantle", "Core"], "tip": "Outside in."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["4th", "1st", "2nd", "3rd"], "tip": "Heat, rise, spread, sink."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["heat", "hot", "core"], ["rise", "less dense"], ["drag", "carry", "move the plates", "pull"]], "tips": ["Heat → density → movement."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Continents were once joined", "Plate boundaries are active", "Continents were once joined", "Plate boundaries are active"], "tip": "Joined in the past, or moving now?"}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["cannot swim", "land", "could not cross"], ["joined", "together", "connected"]], "tips": ["Could it cross the ocean?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["new", "magma", "ridge"], ["magnetic field", "reverse", "line up"], ["spread", "both sides", "move apart", "away"]], "tips": ["New rock, recorded field, moves outwards."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["explain", "mechanism", "how", "what moved"], ["new evidence", "magnetic", "sea floor", "technology"], ["convection", "spreading"]], "tips": ["Missing mechanism, then new evidence."]}]}, "models": {"1": [["Q1", "Crust, then mantle, then core."]], "2": [["Q2", "Heated → rises → spreads, dragging plates → cools and sinks."], ["Q3", "The core heats mantle rock [1], which becomes less dense and rises, then cools and sinks in a circular convection current [1]; the moving mantle drags the plates above it along [1]."]], "3": [["Q4", "Fossils and coastlines: once joined. Belts of earthquakes and volcanoes: active boundaries."], ["Q5", "The reptile lived on land and could not have swum across the Atlantic Ocean [1], so the two continents must once have been joined together [1]."]], "4": [["Q6", "New rock forms from magma at the ridge [1]; as it cools it records the direction of the Earth''s magnetic field, which reverses from time to time [1]; the sea floor spreads out equally on both sides, so the stripes form a mirror image [1]."]], "5": [["Q7", "In 1912 Wegener could not explain what force moved the continents [1]; in the 1960s new technology found evidence such as magnetic stripes on the sea floor [1], which showed sea-floor spreading driven by convection currents, giving a mechanism [1]."]], "6": [["Exit ticket", "Any two: fitting coastlines; matching fossils/rocks; pattern of earthquakes and volcanoes; magnetic stripes on the sea floor."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Name the layer.", "Q2": "Put the convection current in order.", "Q3": "Explain how convection currents in the mantle cause tectonic plates to move.", "Q4": "What does each observation show?", "Q5": "Explain why finding fossils of the same land reptile in South America and Africa is evidence that the continents were once joined.", "Q6": "Explain why the magnetic stripes on each side of a mid-ocean ridge are a mirror image of each other.", "Q7": "Suggest why most scientists did not accept Wegener''s idea in 1912, and why they accepted plate tectonics in the 1960s."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
