insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('a6e7b31d-9475-5e70-b565-2305e0416efb', '62acfba2-963a-5cfb-8908-6a2efc8d6604', 'Unit 1 Density, floating and sinking: Why things float or sink', 'Stage 9 Physics · Objectives 9Pf.01', '/cks9-phys-1/', 'CKS9-PHYS-L1', 21, 60, 10) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-PHYS-L1', 'Unit 1 Density, floating and sinking: Why things float or sink', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Floats", "Sinks", "Floats", "Sinks", "Floats"], "tip": "Compare with 1.0."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Floats", "Sinks", "Floats"], "tip": "Balanced forces."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["2000"], ["balanced", "equal", "floats", "not moving"]], "tips": ["Floating = balanced."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["same mass"], ["larger volume", "more volume", "displace more", "hollow", "air"], ["average density", "less dense", "lower density"]], "tips": ["Mass the same; what changes?"]}, {"kind": "choice", "id": "q3_1", "q": "Q5", "max": 3, "n": 3, "ans": ["Increases", "Decreases", "Increases"], "tip": "More mass in the same volume?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["salt+dens", "denser water", "water more dense", "density of the water increases"], ["egg less dense", "less dense than", "greater upthrust", "more upthrust"]], "tips": ["Which density changed?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["fill", "water in", "take in water"], ["denser", "density increases", "heavier", "sink"], ["pump", "air", "empty", "force out"]], "tips": ["Change the average density."]}]}, "models": {"1": [["Q1", "Less than 1.0 g/cm³ floats; more than 1.0 sinks."]], "2": [["Q2", "Balanced upthrust and weight: floats. Weight bigger: sinks."], ["Q3", "The upthrust is 2000 N [1] because the boat is floating, so the upthrust balances its weight [1]."]], "3": [["Q4", "The mass of clay is the same [1], but the boat shape has a much larger volume including air, so it displaces more water [1]; its average density is now less than water, so it floats [1]."], ["Q5", "Cargo and leaks add mass: average density increases; pumping out water decreases it."]], "4": [["Q6", "Dissolving salt makes the water denser [1], so the egg is now less dense than the salt water (the upthrust can balance its weight) and it floats [1]."]], "5": [["Q7", "To dive, the ballast tanks fill with water [1], which increases the submarine''s mass and average density so it becomes denser than seawater and sinks [1]; to rise, compressed air pushes the water out, lowering its average density so it floats up [1]."]], "6": [["Exit ticket", "Yes: it is less dense than water (1.0 g/cm³)."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Float or sink in water?", "Q2": "Which statement matches?", "Q3": "A floating boat has a weight of 2000 N. State the upthrust on it and explain your answer.", "Q4": "A ball of modelling clay sinks but the same clay shaped into a boat floats. Explain why.", "Q5": "Will the average density increase or decrease?", "Q6": "An egg sinks in tap water but floats when salt is dissolved in the water. Explain why.", "Q7": "Explain how a submarine can dive and then rise to the surface."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
