insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('cf34e26c-97f7-548c-b2c0-8f184eaa8d9c', '62acfba2-963a-5cfb-8908-6a2efc8d6604', 'short', 'A block has a mass of 60 g and a volume of 80 cm³. Calculate its density and state whether it floats in water.', '[]'::jsonb, 3, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cf34e26c-97f7-548c-b2c0-8f184eaa8d9c', 'Density = 60 ÷ 80 [1] = 0.75 g/cm³ [1]; it floats because 0.75 is less than 1.0 g/cm³ [1].', 'Density = 60 ÷ 80 [1] = 0.75 g/cm³ [1]; it floats because 0.75 is less than 1.0 g/cm³ [1].', '[{"text": "Density = 60 ÷ 80", "any": ["60 ÷ 80", "60/80", "60 / 80"], "all": [], "marks": 1}, {"text": "= 0.75 g/cm³", "any": ["0.75"], "all": [], "marks": 1}, {"text": "It floats because 0.75 is less than 1.0 g/cm³", "any": ["float"], "all": [], "marks": 1}]'::jsonb, 'Density = 60 ÷ 80 [1] = 0.75 g/cm³ [1]; it floats because 0.75 is less than 1.0 g/cm³ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
