insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('cff782b7-6a8e-5075-900a-1bc3866a7b63', '62acfba2-963a-5cfb-8908-6a2efc8d6604', 'short', 'Name the upward force that water exerts on a floating object, and state how it compares with the object''s weight.', '[]'::jsonb, 2, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cff782b7-6a8e-5075-900a-1bc3866a7b63', 'Upthrust [1]; it is equal to the weight of the object [1].', 'Upthrust [1]; it is equal to the weight of the object [1].', '[{"text": "Upthrust", "any": ["upthrust"], "all": [], "marks": 1}, {"text": "It is equal to the weight of the object", "any": ["equal", "same", "balance"], "all": [], "marks": 1}]'::jsonb, 'Upthrust [1]; it is equal to the weight of the object [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
