insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('7f179cc7-68ad-5b13-a882-331c7f66a5d2', '62acfba2-963a-5cfb-8908-6a2efc8d6604', 'short', 'Explain why a ship floats higher in sea water than in river water.', '[]'::jsonb, 2, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7f179cc7-68ad-5b13-a882-331c7f66a5d2', 'Sea water is denser than river water [1], so the ship needs to displace a smaller volume to produce enough upthrust, and it floats higher [1].', 'Sea water is denser than river water [1], so the ship needs to displace a smaller volume to produce enough upthrust, and it floats higher [1].', '[{"text": "Sea water is denser than river water", "any": ["salt water is denser", "more dense"], "all": [], "marks": 1}, {"text": "The ship needs to displace a smaller volume to produce enough upthrust, and it floats higher", "any": ["less water", "displace less", "less volume"], "all": [], "marks": 1}]'::jsonb, 'Sea water is denser than river water [1], so the ship needs to displace a smaller volume to produce enough upthrust, and it floats higher [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
