insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('ef7d31aa-c533-587f-b415-2ad7c5fd78a7', '99065b9d-8892-5240-8fa5-f76287911ed0', 'Unit 2 Heat, temperature and conservation of energy: Heat, temperature and energy', 'Stage 9 Physics · Objectives 9Pf.02, 9Pf.03', '/cks9-phys-2/', 'CKS9-PHYS-L2', 22, 60, 20) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-PHYS-L2', 'Unit 2 Heat, temperature and conservation of energy: Heat, temperature and energy', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Temperature", "Heat", "Temperature", "Heat"], "tip": "Energy or hotness?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 3, "n": 3, "ans": ["More energy", "Less energy", "More energy"], "tip": "More mass or bigger rise = more energy."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 3, "pts": [["tea+temperature", "tea has the higher temperature", "tea is hotter"], ["pool+thermal energy", "pool has more"], ["mass", "more water", "more particles"]], "tips": ["Two different questions."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 4, "n": 4, "ans": ["20 J", "60 J", "75 J", "150 J"], "tip": "In − useful = wasted."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["not destroyed", "conserved", "not lost"], ["heat", "thermal", "sound"], ["less", "gravitational potential", "lower"]], "tips": ["Where did the energy go?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 2, "pts": [["heat", "thermal"], ["useful", "all", "no waste", "wanted"]], "tips": ["What does a heater want to make?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["cannot", "impossible", "not possible", "false"], ["created", "conserved", "destroyed"], ["equal", "less", "wasted", "heat"]], "tips": ["Can energy be created?"]}]}, "models": {"1": [["Q1", "Temperature: °C, thermometer. Heat: energy in joules, transferred."], ["Q2", "The bath: it has a far greater mass of water, so it stores far more thermal energy even at a lower temperature."]], "2": [["Q3", "More mass or a bigger temperature rise needs more energy."], ["Q4", "The tea has the higher temperature [1]; the pool has more thermal energy [1] because it has a much greater mass of water (many more particles), each with some energy [1]."]], "3": [["Q5", "100−80=20; 200−140=60; 1000−925=75; 500−350=150 J."], ["Q6", "Energy is not destroyed; it is conserved [1], but some of the ball''s energy is transferred to thermal energy and sound when it hits the ground [1], so less is left as gravitational potential energy and it does not rise as high [1]."]], "4": [["Q7", "A heater is designed to produce thermal energy [1], so all the energy it transfers as heat is useful and none is wasted [1]."]], "5": [["Q8", "The claim cannot be true [1] because energy cannot be created or destroyed [1]; the energy out can at most equal the energy in, and in practice some is always wasted as heat, so useful energy out is less [1]."]], "6": [["Exit ticket", "Temperature is how hot something is (°C); heat is energy transferred because of a temperature difference (J)."]]}, "labels": {"q1_1": "Q2", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Heat or temperature?", "Q2": "A sparkler spark is 1000 °C but a bath is 40 °C. Which has more thermal energy, and why?", "Q3": "More or less energy needed?", "Q4": "A cup of tea at 80 °C and a swimming pool at 25 °C. Which has the higher temperature and which has more thermal energy? Explain.", "Q5": "Calculate the wasted energy.", "Q6": "A ball is dropped and does not bounce as high as the height it was dropped from. Explain this using conservation of energy.", "Q7": "An electric heater is said to be \"100% efficient\". Use the idea of useful and wasted energy to explain why.", "Q8": "An advert says a new machine \"gives out more energy than you put in\". Use the law of conservation of energy to evaluate this claim."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
