insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('87dfd4c0-0b6d-5f04-b2c7-19d8d8965762', '99065b9d-8892-5240-8fa5-f76287911ed0', 'short', 'A light bulb is supplied with 60 J of electrical energy. It gives out 6 J of light. Calculate the wasted energy and state the form it is wasted as.', '[]'::jsonb, 2, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('87dfd4c0-0b6d-5f04-b2c7-19d8d8965762', '60 − 6 = 54 J [1], wasted as heat (thermal energy) [1].', '60 − 6 = 54 J [1], wasted as heat (thermal energy) [1].', '[{"text": "60 − 6 = 54 J", "any": ["54"], "all": [], "marks": 1}, {"text": "Wasted as heat (thermal energy)", "any": ["heat", "thermal"], "all": [], "marks": 1}]'::jsonb, '60 − 6 = 54 J [1], wasted as heat (thermal energy) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
