insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('31ffa635-f579-55b3-9f30-0de73c5ddf84', '99065b9d-8892-5240-8fa5-f76287911ed0', 'short', 'State the law of conservation of energy.', '[]'::jsonb, 1, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('31ffa635-f579-55b3-9f30-0de73c5ddf84', 'Energy cannot be created or destroyed, only transferred [1].', 'Energy cannot be created or destroyed, only transferred [1].', '[{"text": "Energy cannot be created or destroyed, only transferred", "any": ["cannot be created", "not created or destroyed", "neither created nor destroyed"], "all": [], "marks": 1}]'::jsonb, 'Energy cannot be created or destroyed, only transferred [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
