insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('e4404c70-0e78-50ce-bb0c-5dcbe95f1dd6', '99065b9d-8892-5240-8fa5-f76287911ed0', 'short', 'Explain why a large pan of water at 60 °C can melt more ice than a small cup of water at 60 °C.', '[]'::jsonb, 2, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e4404c70-0e78-50ce-bb0c-5dcbe95f1dd6', 'The pan has a greater mass of water [1], so it stores more thermal energy at the same temperature and can transfer more energy to the ice [1].', 'The pan has a greater mass of water [1], so it stores more thermal energy at the same temperature and can transfer more energy to the ice [1].', '[{"text": "The pan has a greater mass of water", "any": ["more mass", "more water", "larger mass"], "all": [], "marks": 1}, {"text": "It stores more thermal energy at the same temperature and can transfer more energy to the ice", "any": ["more thermal energy", "more energy", "more heat"], "all": [], "marks": 1}]'::jsonb, 'The pan has a greater mass of water [1], so it stores more thermal energy at the same temperature and can transfer more energy to the ice [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
