insert into public.topics (id, subject_id, programme, code, name, summary, sort_order) values ('5b803469-8d12-51db-a1dd-9cdf06245d1d', 'c6c87150-0452-5067-bfff-23da7d0912d9', 'Stage 9', 'S9.3', 'Unit 3 Thermal energy transfer and cooling', 'Objectives 9Pf.04, 9Pf.05, 9Pf.06', 903) on conflict (id) do update set name = excluded.name, summary = excluded.summary, sort_order = excluded.sort_order;
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('51a9e5a3-84b5-5e97-b02b-712333eeb03e', '5b803469-8d12-51db-a1dd-9cdf06245d1d', 'Unit 3 Thermal energy transfer and cooling: How thermal energy moves', 'Stage 9 Physics · Objectives 9Pf.04, 9Pf.05, 9Pf.06', '/cks9-phys-3/', 'CKS9-PHYS-L3', 27, 60, 30) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-PHYS-L3', 'Unit 3 Thermal energy transfer and cooling: How thermal energy moves', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["From A to B", "From B to A", "From B to A", "From A to B"], "tip": "Hot → cold."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Good conductor", "Insulator", "Good conductor", "Insulator", "Insulator"], "tip": "Metals conduct."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["vibrate", "vibrating"], ["pass", "collide", "neighbour", "next"], ["free electron", "electrons"]], "tips": ["Vibrations passed on."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Radiation", "Conduction", "Convection", "Radiation", "Convection"], "tip": "Particles touching, fluid moving, or waves?"}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["heat", "warm", "hot"], ["less dense", "rise", "expand"], ["sink", "convection", "cooler water"]], "tips": ["What does hot water do?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["evaporat"], ["most energy", "fastest", "energetic", "escape"], ["lower", "cooler", "average", "temperature falls"]], "tips": ["Who leaves, who stays?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["vacuum"], ["conduction", "convection"], ["silver", "shiny", "reflect", "radiation"], ["lid", "stopper", "cap", "evaporat"]], "tips": ["Attack each method."]}]}, "models": {"1": [["Q1", "Always from the hotter to the colder."]], "2": [["Q2", "Metals conduct well; wool, plastic and trapped air insulate."], ["Q3", "Particles at the hot end gain energy and vibrate more [1]; they pass this energy to neighbouring particles by colliding with them [1]; in metals, free electrons also carry energy quickly along the rod [1]."]], "3": [["Q4", "Space: radiation. Solid: conduction. Moving fluid: convection."], ["Q5", "Water near the element is heated first [1]; it expands, becomes less dense and rises [1], while cooler, denser water sinks to take its place, so a convection current heats all the water [1]."]], "4": [["Q6", "Sweat on the skin evaporates [1]; the particles with the most energy escape from the liquid [1], leaving particles with a lower average energy, so the skin''s temperature falls [1]."]], "5": [["Q7", "A vacuum between the double walls has no particles [1], so energy cannot be transferred across it by conduction or convection [1]; the shiny silvered walls reflect infrared radiation back towards the drink [1]; the plastic stopper reduces conduction and stops convection and evaporation from the top [1]."]], "6": [["Exit ticket", "Conduction, convection and radiation."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which way does thermal energy flow?", "Q2": "Conductor or insulator?", "Q3": "Explain, using particles, how energy travels along a metal rod held in a flame.", "Q4": "Conduction, convection or radiation?", "Q5": "Explain why the heating element of an electric kettle is at the bottom.", "Q6": "Explain how sweating helps to cool the body on a hot day.", "Q7": "Explain how a vacuum flask keeps a hot drink hot. Refer to conduction, convection and radiation."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
