insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d1323b5f-433e-59dd-b104-520d64ae01ba', 'Warmth gives the water particles more energy so more escape (evaporate) [1]; the wind carries the water vapour away from the clothes so evaporation continues faster [1].', 'Warmth gives the water particles more energy so more escape (evaporate) [1]; the wind carries the water vapour away from the clothes so evaporation continues faster [1].', '[{"text": "Warmth gives the water particles more energy so more escape (evaporate)", "any": ["warm", "energy", "temperature"], "all": [], "marks": 1}, {"text": "The wind carries the water vapour away from the clothes so evaporation continues faster", "any": ["wind", "carries away", "blows away", "water vapour"], "all": [], "marks": 1}]'::jsonb, 'Warmth gives the water particles more energy so more escape (evaporate) [1]; the wind carries the water vapour away from the clothes so evaporation continues faster [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
