insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-PHYS-L4', 'Unit 4 Sound waves: Seeing sound: waveforms and interference', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Amplitude", "Frequency", "Frequency", "Amplitude"], "tip": "Height or how many?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Taller waves", "Waves closer together", "Shorter waves", "Waves further apart"], "tip": "Loudness = height; pitch = spacing."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["taller", "larger amplitude", "bigger amplitude", "higher amplitude"], ["closer", "more waves", "higher frequency"]], "tips": ["Height and spacing."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["1000 Hz", "500 Hz", "Ultrasound", "Infrasound"], "tip": "f = waves ÷ time."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["silence", "no sound", "quiet", "cancel"], ["peak+trough", "add to zero", "opposite"]], "tips": ["Add them together."]}, {"kind": "choice", "id": "q4_1", "q": "Q6", "max": 4, "n": 4, "ans": ["Reinforce (louder)", "Cancel (quieter)", "Reinforce (louder)", "Cancel (quieter)"], "tip": "In step adds; out of step subtracts."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["microphone", "detect", "pick up"], ["opposite", "inverted", "out of step", "trough"], ["cancel", "interfer"]], "tips": ["Detect, invert, add."]}]}, "models": {"1": [["Q1", "Amplitude is the height (loudness); frequency is waves per second (pitch)."]], "2": [["Q2", "Louder: taller. Higher: closer together. Quieter: shorter. Lower: further apart."], ["Q3", "The loud note has a larger amplitude (taller waves) [1] and the high note has a higher frequency (more waves, closer together) [1]."]], "3": [["Q4", "10÷0.01 = 1000 Hz; 50÷0.1 = 500 Hz; above 20 000 Hz is ultrasound; below 20 Hz is infrasound."]], "4": [["Q5", "Very little or no sound is heard [1] because each peak is cancelled by a trough, so the waves add together to give zero amplitude [1]."], ["Q6", "In step: reinforce. Out of step: cancel."]], "5": [["Q7", "A microphone detects the noise outside [1]; the headphones produce a sound wave that is the exact opposite (out of step) of the noise [1]; the two waves interfere and cancel, so much less noise is heard [1]."]], "6": [["Exit ticket", "Amplitude shows loudness; frequency shows pitch."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q5", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which feature of the waveform?", "Q2": "Describe the waveform.", "Q3": "In your book, draw a waveform for a quiet, low note. Then draw a second waveform for a loud, high note. Describe two differences between them.", "Q4": "Calculate or choose.", "Q5": "Two identical waves meet exactly out of step (each peak meets a trough). Describe and explain what is heard.", "Q6": "Reinforce or cancel?", "Q7": "Explain how noise-cancelling headphones reduce the noise you hear."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
