insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('4e2c56c6-a93e-5aa5-8e58-3d47ac19d8a5', '5b270eba-0d78-5783-9f57-9cbb33250e54', 'Unit 5 Series and parallel circuits, resistance: Current, voltage and resistance in circuits', 'Stage 9 Physics · Objectives 9Pe.01, 9Pe.02, 9Pe.03, 9Pe.04', '/cks9-phys-5/', 'CKS9-PHYS-L5', 26, 60, 50) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-PHYS-L5', 'Unit 5 Series and parallel circuits, resistance: Current, voltage and resistance in circuits', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Series", "Parallel", "Series", "Parallel"], "tip": "One path or several?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Ammeter", "Voltmeter", "Resistor", "Buzzer", "Ammeter"], "tip": "A or V?"}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["0.2 A", "3 V", "6 V", "1.5 A", "0.5 A"], "tip": "Series shares voltage; parallel splits current."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["0.5"], ["add up", "split", "total", "subtract"]], "tips": ["Branches add to total."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["2 Ω", "4 Ω", "10 Ω", "0.5 A"], "tip": "R = V ÷ I."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 3, "pts": [["9 ÷ 0.3", "9/0.3", "9 / 0.3", "v ÷ i", "v/i"], ["30"], ["ohm", "Ω"]], "tips": ["R = V ÷ I."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["parallel"], ["switch+each", "own switch", "switch in each branch", "separate switch"], ["full voltage", "independent", "other keeps working", "does not affect"]], "tips": ["Branches with switches."]}]}, "models": {"1": [["Q1", "One loop: series. Separate branches: parallel."]], "2": [["Q2", "Ammeter: series, A. Voltmeter: across, V. Resistor: rectangle."]], "3": [["Q3", "Series: same current, shared voltage. Parallel: full voltage, currents add up."], ["Q4", "0.9 − 0.4 = 0.5 A [1] because the currents in the branches add up to the total current [1]."]], "4": [["Q5", "6÷3=2 Ω; 12÷3=4 Ω; 5÷0.5=10 Ω; I = 5÷10 = 0.5 A."], ["Q6", "R = V ÷ I = 9 ÷ 0.3 [1] = 30 [1] Ω (ohms) [1]."]], "5": [["Q7", "Connect the lamp and the buzzer in parallel with the battery [1], with a switch in each branch [1]; each branch gets the full voltage and switching one off does not affect the other [1]."]], "6": [["Exit ticket", "It splits between the branches; the branch currents add up to the total."]]}, "labels": {"q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Series or parallel?", "Q2": "Name the symbol or rule.", "Q3": "Use the patterns.", "Q4": "A parallel circuit has a total current of 0.9 A. One branch carries 0.4 A. Calculate the current in the other branch and explain your method.", "Q5": "Calculate.", "Q6": "The voltage across a resistor is 9 V and the current through it is 0.3 A. Calculate its resistance, with the unit.", "Q7": "Design a circuit, described in words, where a lamp and a buzzer can each be switched on and off separately from one battery. Explain why you chose this arrangement."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
