insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-PHYS-L6', 'Unit 6 Asteroids, the Moon and nebulae (Earth and Space): Asteroids, the Moon and the birth of stars', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["True", "True", "False", "True"], "tip": "Rocky leftovers."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 4, "pts": [["dust", "soot", "debris"], ["block", "sunlight", "dark"], ["photosynth", "plants die", "cold"], ["food", "starve", "food chain"]], "tips": ["Dust → light → plants → food."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Supports", "Supports", "Supports", "Does not support"], "tip": "Which fit a giant impact?"}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 3, "pts": [["collid", "hit", "impact"], ["debris", "material", "rock"], ["gravity", "pulled together", "clumped"]], "tips": ["Hit, debris, gravity."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["dust", "gas"], ["gravity", "pulled together", "collapse"], ["star", "born", "form"]], "tips": ["What is in it, what pulls it, what forms."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["iridium", "clay layer"], ["crater", "chicxulub"], ["more confident", "support", "other explanation", "reliable", "not chance"]], "tips": ["Two evidence + why."]}]}, "models": {"1": [["Q1", "Asteroids are rocky leftovers, mostly in the belt between Mars and Jupiter; large impacts make craters."]], "2": [["Q2", "The impact threw dust and soot into the atmosphere [1], which blocked sunlight [1], so it became colder and plants could not photosynthesise and died [1]; herbivores and then carnivores ran out of food and starved [1]."]], "3": [["Q3", "Similar rocks, a small core and signs of melting all fit the giant impact theory."], ["Q4", "A Mars-sized body (Theia) collided with the young Earth [1]; debris from both was thrown into orbit around the Earth [1] and was pulled together by gravity to form the Moon [1]."]], "4": [["Q5", "A nebula is a cloud of dust and gas [1]; gravity pulls parts of it together so they collapse and heat up [1]; when hot enough, new stars form there, like a nursery for stars [1]."]], "5": [["Q6", "A worldwide layer of iridium-rich clay from 66 million years ago [1] and the huge Chicxulub crater of the same age [1]; several independent pieces of evidence that agree make scientists more confident and help rule out other explanations [1]."]], "6": [["Exit ticket", "A cloud of dust and gas in space where stars form (a stellar nursery)."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "True or false?", "Q2": "Explain how an asteroid impact could cause the extinction of large animals such as dinosaurs.", "Q3": "Does the observation support the collision theory?", "Q4": "Describe the collision theory of the formation of the Moon.", "Q5": "Explain why a nebula is called a \"stellar nursery\".", "Q6": "Some scientists once thought the dinosaurs died out because of huge volcanic eruptions. Suggest two pieces of evidence that support the asteroid theory, and explain why scientists look for more than one piece of evidence."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
