insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-MATHS-L1', 'Unit 1 Indices, standard form and surds: Powers, standard form and surds', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["2⁷", "5⁴", "1", "1/8", "3⁻²"], "tip": "Add or subtract the indices."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["3.4 × 10⁵", "7.2 × 10⁻⁴", "6 × 10⁹", "5.08 × 10⁻²"], "tip": "Count the places the point moves."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["0.0045"], ["8.1 × 10", "8.1 x 10", "8.1×10", "8.1x10"]], "tips": ["Move the point."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["6 × 10⁹", "4 × 10⁴", "2 × 10⁶", "1.5 × 10⁻²"], "tip": "Numbers then powers."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["1.4 × 10⁻² ÷ 7 × 10⁻⁶", "÷", "divide", "0.2 × 10"], ["2000", "2 × 10³", "2 x 10^3", "2×10³"]], "tips": ["Total length ÷ one length."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["Rational", "Irrational", "Rational", "Irrational", "Rational"], "tip": "Can it be a fraction?"}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["8 and 9", "8 & 9", "between 8 and 9"], ["64", "81"]], "tips": ["Square numbers either side."]}, {"kind": "text", "id": "q4_2", "q": "Q8", "max": 2, "pts": [["24.5"], ["25.5"]], "tips": ["Half a unit either side."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 3, "pts": [["÷", "divide", "1.5 × 10⁸ ÷ 3 × 10⁵", "0.5 × 10"], ["500"], ["8.3", "8 minutes 20", "8 min 20", "8.33"]], "tips": ["Distance ÷ speed."]}]}, "models": {"1": [["Q1", "2³⁺⁴ = 2⁷; 5⁶⁻² = 5⁴; 7⁰ = 1; 2⁻³ = 1/2³ = 1/8; 3²⁻⁴ = 3⁻²."]], "2": [["Q2", "340 000 = 3.4 × 10⁵; 0.000 72 = 7.2 × 10⁻⁴; 6 000 000 000 = 6 × 10⁹; 0.0508 = 5.08 × 10⁻²."], ["Q3", "4.5 × 10⁻³ = 0.0045 [1]; 81 000 000 = 8.1 × 10⁷ [1]."]], "3": [["Q4", "6 × 10⁹; 4 × 10⁴; 20 × 10⁵ = 2 × 10⁶; 15 × 10⁻³ = 1.5 × 10⁻²."], ["Q5", "(1.4 × 10⁻²) ÷ (7 × 10⁻⁶) = 0.2 × 10⁴ [1] = 2000 (2 × 10³) cells [1]."]], "4": [["Q6", "3/7, 0.25 and √16 = 4 are rational; √2 and π are irrational."], ["Q7", "√70 lies between 8 and 9 [1] because 8² = 64 and 9² = 81, and 70 is between 64 and 81 [1]."], ["Q8", "Lower bound 24.5 m [1]; upper bound 25.5 m [1]."]], "5": [["Q9", "Time = (1.5 × 10⁸) ÷ (3 × 10⁵) = 0.5 × 10³ [1] = 500 seconds [1] ≈ 8.3 minutes (8 minutes 20 seconds) [1]."]], "6": [["Exit ticket", "3.6 × 10⁻⁴."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q4_2": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Simplify, giving the answer as a single power or number.", "Q2": "Write in standard form.", "Q3": "Write 4.5 × 10⁻³ as an ordinary number, and write 81 000 000 in standard form.", "Q4": "Calculate. Give the answer in standard form.", "Q5": "A red blood cell is 7 × 10⁻⁶ m wide. How many cells laid side by side would make a line 1.4 × 10⁻² m long? Show your working.", "Q6": "Rational or irrational?", "Q7": "Between which two whole numbers does √70 lie? Explain how you know.", "Q8": "A rope is 25 m long, to the nearest metre. Write its lower and upper bounds.", "Q9": "The Sun is 1.5 × 10⁸ km from Earth. Light travels 3 × 10⁵ km per second. How many seconds does sunlight take to reach Earth? Give your answer as an ordinary number and in minutes."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
