insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-MATHS-L2', 'Unit 2 Fractions, decimals and percentages: Recurring decimals, fraction calculations and compound change', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Terminating", "Recurring", "Terminating", "Recurring", "Terminating"], "tip": "Factors of the denominator."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["1 5/12", "3 1/3", "1 7/8", "1/6"], "tip": "Common denominator; reciprocal for ÷."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["16/5", "16/5 ÷ 8/5", "× 5/8", "x 5/8"], ["2"]], "tips": ["Improper fractions, then reciprocal."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["1.15", "0.8", "1.05", "0.97"], "tip": "1 ± r/100."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["0.9", "× 0.9", "x 0.9", "10 800"], ["9720"]], "tips": ["Multiply by 0.9 twice."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["320"], ["36"], ["smaller", "new price", "reduced price", "less"]], "tips": ["Multiply twice."]}], "5": [{"kind": "choice", "id": "q5_0", "q": "Q7", "max": 4, "n": 4, "ans": ["0.024", "80", "0.35", "1.2"], "tip": "Count decimal places; scale division."}, {"kind": "text", "id": "q5_1", "q": "Q8", "max": 2, "pts": [["50 × 0.2 ÷ 0.5", "50×0.2÷0.5", "50, 0.2", "0.5"], ["20"]], "tips": ["Round, then calculate."]}]}, "models": {"1": [["Q1", "8 = 2³ and 40 = 2³ × 5 terminate; 6 and 9 have a factor 3 (recurring); 9/12 = 3/4 terminates."]], "2": [["Q2", "17/12 = 1 5/12; 20/6 = 3 1/3; 15/8 = 1 7/8; 5/6 − 4/6 = 1/6."], ["Q3", "16/5 ÷ 8/5 = 16/5 × 5/8 [1] = 80/40 = 2 [1]."]], "3": [["Q4", "1.15; 0.8; 1.05; 0.97."], ["Q5", "12 000 × 0.9² [1] = $9720 [1]."]], "4": [["Q6", "500 × 0.8 × 0.8 = $320 [1]; the overall reduction is 180/500 = 36% [1]; it is not 40% because the second 20% is of the new, smaller price [1]."]], "5": [["Q7", "0.024; 80; 0.35; 1.2."], ["Q8", "≈ 50 × 0.2 ÷ 0.5 [1] = 10 ÷ 0.5 = 20 [1]."]], "6": [["Exit ticket", "1.08."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q5_1": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Terminating or recurring?", "Q2": "Calculate.", "Q3": "Work out 3 1/5 ÷ 1 3/5. Show your working.", "Q4": "Choose the multiplier.", "Q5": "A car worth $12 000 loses 10% of its value each year. Work out its value after 2 years.", "Q6": "A phone costs $500. Its price is reduced by 20% and then by another 20%. Find the final price and the overall percentage reduction. Explain why it is not 40%.", "Q7": "Calculate without a calculator.", "Q8": "Estimate 49.7 × 0.198 ÷ 0.51 by rounding each number to 1 significant figure. Show your rounded numbers."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
