insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-MATHS-L3', 'Unit 3 Ratio and proportion: Direct and inverse proportion', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Direct", "Inverse", "Inverse", "Direct"], "tip": "Both up, or one up and one down?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["1.75"], ["21"]], "tips": ["Cost of one first."]}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["0.64", "0.62", "6.4", "6.2", "per 100"], ["750"]], "tips": ["Cost per 100 g."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["3 days", "2 hours", "12 days", "45 minutes"], "tip": "Find the product first."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["60"], ["20"]], "tips": ["Total person-hours."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["7 parts", "50", "350 ÷ 7"], ["100"]], "tips": ["Total parts."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["inverse"], ["1800", "120 × 15"], ["12"]], "tips": ["More students → fewer days."]}]}, "models": {"1": [["Q1", "Tickets–cost and flour–cakes are direct; speed–time and workers–time are inverse."]], "2": [["Q2", "1 notebook costs 8.75 ÷ 5 = $1.75 [1]; 12 cost 12 × 1.75 = $21 [1]."], ["Q3", "500 g: 64 cents per 100 g; 750 g: 62 cents per 100 g [1]; so the 750 g pack is the better buy [1]."]], "3": [["Q4", "24÷8 = 3; 180÷90 = 2; 24÷2 = 12; 90÷2 = 45."], ["Q5", "5 × 12 = 60 person-hours [1]; 60 ÷ 3 = 20 hours [1]."]], "4": [["Q6", "1 + 2 + 4 = 7 parts, so 1 part = 350 ÷ 7 = 50 kg [1]; sand = 2 × 50 = 100 kg [1]."]], "5": [["Q7", "This is inverse proportion because more students make the food last fewer days [1]; total = 120 × 15 = 1800 student-days [1]; 1800 ÷ 150 = 12 days [1]."]], "6": [["Exit ticket", "5 days (inverse proportion: 60 ÷ 12)."]]}, "labels": {"q2_0": "Q2", "q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Direct or inverse proportion?", "Q2": "5 notebooks cost $8.75. Find the cost of 12 notebooks.", "Q3": "A 500 g pack costs $3.20 and a 750 g pack costs $4.65. Which is the better buy? Show your working.", "Q4": "Solve.", "Q5": "It takes 5 people 12 hours to paint a hall. How long would it take 3 people working at the same rate?", "Q6": "Concrete is made from cement, sand and gravel in the ratio 1 : 2 : 4. How much sand is needed to make 350 kg of concrete?", "Q7": "A school has enough food to feed 120 students for 15 days. If 30 more students join, how many days will the food last? Explain whether this is direct or inverse proportion."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
