insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-MATHS-L4', 'Unit 4 Expressions and formulae: Expanding, simplifying and changing the subject', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["x⁷", "y⁶", "a⁶", "12x⁷", "3a⁴"], "tip": "Add, subtract or multiply indices."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["x² + 8x + 15", "x² − 2x − 8", "x² + 12x + 36", "x² − 9"], "tip": "Four multiplications, then collect."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["2x² − 6x + x − 3", "2x^2 - 6x + x - 3", "2x² - 6x + x - 3", "2x²", "2x^2"], ["− 5x − 3", "-5x-3", "- 5x - 3", "−5x − 3", "-5x - 3"]], "tips": ["Four terms first."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["2x + 3", "2x", "x + 5", "3a/2"], "tip": "Cancel common factors."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["y − 4", "y - 4", "y-4"], ["/5", "÷ 5", "/ 5", "over 5", "÷5"]], "tips": ["Undo +4, then ×5."]}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 3, "pts": [["f − 32", "f - 32", "f-32"], ["× 5", "5(", "5 (", "5f", "x 5", "*5"], ["/9", "÷ 9", "/ 9", "over 9", "÷9"]], "tips": ["Subtract 32, ×5, ÷9."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["(x + 4)(x − 1)", "(x+4)(x-1)", "(x + 4)(x - 1)"], ["x² + 3x − 4", "x^2 + 3x - 4", "x² + 3x - 4", "x^2+3x-4"], ["50"]], "tips": ["Length × width."]}]}, "models": {"1": [["Q1", "x⁷; y⁶; a⁶; 12x⁷; 3a⁴."]], "2": [["Q2", "x² + 8x + 15; x² − 2x − 8; x² + 12x + 36; x² − 9."], ["Q3", "2x² − 6x + x − 3 [1] = 2x² − 5x − 3 [1]."]], "3": [["Q4", "2x + 3; 2x; x + 5; 3a/2."]], "4": [["Q5", "y − 4 = 5x [1], so x = (y − 4)/5 [1]."], ["Q6", "F − 32 = 9C/5 [1]; 5(F − 32) = 9C [1]; C = 5(F − 32)/9 [1]."]], "5": [["Q7", "Area = (x + 4)(x − 1) [1] = x² + 3x − 4 [1]; when x = 6: 36 + 18 − 4 = 50 cm² [1]."]], "6": [["Exit ticket", "x² + 9x + 14."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q5", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Simplify.", "Q2": "Expand and simplify.", "Q3": "Expand and simplify (2x + 1)(x − 3).", "Q4": "Simplify.", "Q5": "Make x the subject of y = 5x + 4.", "Q6": "Make C the subject of F = 9C/5 + 32.", "Q7": "A rectangle has length (x + 4) cm and width (x − 1) cm. Write an expanded expression for its area. Then find the area when x = 6."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
