insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('c76956f1-e753-5dee-8038-97cda016394a', 'e79baebc-6e63-550b-88ce-acc1eb4aaf68', 'short', 'A taxi charges $3 plus $1.50 per km. Write a formula for the cost C in dollars for d km, and find the cost of a 12 km journey.', '[]'::jsonb, 2, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
