insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-MATHS-L5', 'Unit 5 Equations, simultaneous equations and inequalities: Solving equations, simultaneous equations and inequalities', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["5", "4", "13", "−2"], "tip": "Balance both sides."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["20/x = 4", "20 = 4x", "4x"], ["5"]], "tips": ["Subtract 1 first."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["x = 7", "x=7"], ["y = 3", "y=3"]], "tips": ["Add the equations."]}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 3, "pts": [["2x = 8", "subtract"], ["x = 4", "x=4"], ["y = 2", "y=2"]], "tips": ["Subtract to remove y."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 3, "n": 3, "ans": ["(3, 4)", "(2, 6)", "(1, 3)"], "tip": "Set equal and solve."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["4x ≥ 16", "4x >= 16"], ["x ≥ 4", "x >= 4"], ["4, 5, 6", "4,5,6", "4 5 6"]], "tips": ["Solve, then list."]}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["90n ≤ 500", "90n <= 500", "90 n ≤ 500"], ["5"]], "tips": ["At most $500."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["2p = 3.6", "subtract", "2 pens"], ["1.8"], ["1.0", "1.00", "$1"]], "tips": ["Subtract to remove rulers."]}]}, "models": {"1": [["Q1", "x = 5; x = 4; x = 13; 3x = −6 so x = −2."], ["Q2", "20/x = 4 so 20 = 4x [1], x = 5 [1]."]], "2": [["Q3", "Adding: 2x = 14 so x = 7 [1]; then y = 10 − 7 = 3 [1]."], ["Q4", "Subtracting: 2x = 8 [1], x = 4 [1]; 4 + 2y = 8 so y = 2 [1]."]], "3": [["Q5", "x + 1 = 7 − x → x = 3; 2x + 2 = 10 − 2x → x = 2; 3x = x + 2 → x = 1."]], "4": [["Q6", "4x ≥ 16 [1], x ≥ 4 [1]; the integers are 4, 5, 6 [1]."], ["Q7", "90n ≤ 500 [1]; n ≤ 5.55… so the school can buy at most 5 phones [1]."]], "5": [["Q8", "Subtracting: 2 pens = 3.60 [1], so a pen costs $1.80 [1]; 1.80 + 2r = 3.80 so a ruler costs $1.00 [1]."]], "6": [["Exit ticket", "x = 6."]]}, "labels": {"q1_1": "Q2", "q2_0": "Q3", "q2_1": "Q4", "q4_0": "Q6", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Solve.", "Q2": "Solve 20/x + 1 = 5.", "Q3": "Solve the simultaneous equations x + y = 10 and x − y = 4.", "Q4": "Solve 3x + 2y = 16 and x + 2y = 8.", "Q5": "Where do the lines cross?", "Q6": "Solve 4x + 5 ≥ 21 and list the integer values of x that also satisfy x < 7.", "Q7": "Phones cost $90 each. A school has $500. Write an inequality for the number of phones n it can buy, and solve it.", "Q8": "A shop sells pens and rulers. 3 pens and 2 rulers cost $7.40. 1 pen and 2 rulers cost $3.80. Find the cost of one pen and one ruler."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
