insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('1e36d88b-0d5a-5a24-a95b-4a354fece73b', '9fd0d7d1-0326-5fe1-a574-e2e3f5ad493f', 'Unit 6 Sequences and functions: Finding the rule', 'Stage 9 Mathematics · Objectives 9As.01, 9As.02, 9As.03, 9As.04', '/cks9-maths-6/', 'CKS9-MATHS-L6', 24, 60, 60) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-MATHS-L6', 'Unit 6 Sequences and functions: Finding the rule', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["17", "−3", "36", "48"], "tip": "Look at the change."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["3n + 2", "4n − 1", "5n + 3", "23 − 3n"], "tip": "Difference, then adjust."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["6n"], ["6n + 1", "6n+1"], ["301"]], "tips": ["Difference 6."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["n² + 1", "n² − 3", "2n²", "n³"], "tip": "Compare with 1, 4, 9, 16."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["5, 8, 13, 20", "5,8,13,20", "5 8 13 20"], ["difference", "not constant", "not the same", "second difference"]], "tips": ["n = 1, 2, 3, 4."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["13", "8", "7", "y = 2x + 3"], "tip": "Reverse the operations."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["3n + 1", "3n+1"], ["33"], ["yes", "n = 33", "is in"]], "tips": ["Solve 3n + 1 = 100."]}]}, "models": {"1": [["Q1", "+3 → 17; −3 → −3; square numbers → 36; ×2 → 48."]], "2": [["Q2", "3n + 2; 4n − 1; 5n + 3; 23 − 3n."], ["Q3", "The difference is 6 so it starts 6n [1]; nth term = 6n + 1 [1]; 50th term = 301 [1]."]], "3": [["Q4", "n² + 1; n² − 3; 2n²; n³."], ["Q5", "5, 8, 13, 20 [1]; the differences are 3, 5, 7, which are not constant, so it is not linear [1]."]], "4": [["Q6", "13; 8; 7; y = 2x + 3."]], "5": [["Q7", "nth term = 3n + 1 [1]; 3n + 1 = 100 gives n = 33 [1], a whole number, so yes: pattern 33 uses exactly 100 tiles [1]."]], "6": [["Exit ticket", "4n − 2."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Next term?", "Q2": "nth term?", "Q3": "Find the nth term of 7, 13, 19, 25, … and the 50th term.", "Q4": "Match the nth term.", "Q5": "Write the first four terms of the sequence with nth term n² + 4, and explain how you know it is not linear.", "Q6": "Find the missing value.", "Q7": "A tile pattern has 4, 7, 10, 13 … tiles. Find the nth term and decide whether a pattern could use exactly 100 tiles. Explain."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
