insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-MATHS-L7', 'Unit 7 Graphs: Straight-line and quadratic graphs', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["5", "0", "−3", "−4"], "tip": "Square, then subtract 4."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["m = 3, c = 2", "m = −2, c = 5", "m = ½, c = −1", "m = 4, c = 0"], "tip": "Read m and c."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["6/3", "6 ÷ 3", "4 − (−2)", "4 - -2"], ["gradient 2", "m = 2", "gradient is 2", "m=2", "= 2"], ["y = 2x − 2", "y=2x-2", "y = 2x - 2"]], "tips": ["Gradient, then c."]}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["−1", "-1"], ["y = −x + 5", "y = 5 − x", "y=-x+5", "y = -x + 5", "y=5-x"]], "tips": ["Down 5, across 5."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["15"], ["15 km/h", "same speed", "both 15"], ["flat", "horizontal", "stopped"]], "tips": ["Distance ÷ time."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["per km", "per kilometre", "each km", "gradient"], ["fixed", "starting", "basic", "intercept", "charge before"], ["12.6", "12.60"]], "tips": ["Gradient and intercept in context."]}]}, "models": {"1": [["Q1", "9 − 4 = 5; 4 − 4 = 0; 1 − 4 = −3; 0 − 4 = −4."]], "2": [["Q2", "m = 3, c = 2; m = −2, c = 5; m = ½, c = −1; m = 4, c = 0."]], "3": [["Q3", "Gradient = (4 − (−2)) ÷ 3 = 6/3 [1] = 2 [1]; y = 2x − 2 [1]."], ["Q4", "Gradient = −5 ÷ 5 = −1 [1]; y = −x + 5 [1]."]], "4": [["Q5", "First part: 30 ÷ 2 = 15 km/h [1]; third part: 15 ÷ 1 = 15 km/h, the same speed, so the two sloping lines are equally steep [1]; the stop shows as a flat (horizontal) line [1]."]], "5": [["Q6", "1.2 is the cost per km ($1.20 for each km) [1]; 3 is the fixed charge ($3) before you travel [1]; C = 1.2 × 8 + 3 = $12.60 [1]."]], "6": [["Exit ticket", "Gradient 4, y-intercept −7."]]}, "labels": {"q3_0": "Q3", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Complete the table for y = x² − 4.", "Q2": "Gradient and intercept.", "Q3": "A line passes through (0, −2) and (3, 4). Find its equation.", "Q4": "Find the equation of the line through (0, 5) and (5, 0).", "Q5": "A cyclist travels 30 km in 2 hours, stops for 30 minutes, then travels 15 km in 1 hour. Find her speed in each moving part and describe the graph.", "Q6": "The cost C dollars of a taxi ride of d km is C = 1.2d + 3. Explain what 1.2 and 3 mean, and find the cost of an 8 km ride."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
