insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('7436861c-100d-538e-8802-7e7dfe9492f2', 'fd531a34-c732-5a32-a875-99b63c460b6a', 'Unit 8 Area, volume and surface area: Circles, prisms and cylinders', 'Stage 9 Mathematics · Objectives 9Gg.01, 9Gg.02, 9Gg.03, 9Gg.04, 9Gg.05', '/cks9-maths-8/', 'CKS9-MATHS-L8', 23, 60, 80) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-MATHS-L8', 'Unit 8 Area, volume and surface area: Circles, prisms and cylinders', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["31.4 cm", "78.5 cm²", "18.8 cm", "28.3 cm²"], "tip": "C = πd, A = πr²."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["64"], ["25.1", "8π", "25.13"], ["89.1", "89.13"]], "tips": ["Square + half a circle."]}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 4, "n": 4, "ans": ["1000 cm³", "10 000 cm²", "0.25 m", "2 500 000 cm³"], "tip": "Square or cube the scale factor."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["0.6", "radius"], ["1.7", "1.69", "1.70"], ["1696", "1700", "1696.5", "1 696"]], "tips": ["Radius first."]}, {"kind": "choice", "id": "q3_1", "q": "Q5", "max": 3, "n": 3, "ans": ["120 cm³", "282.7 cm³", "240 cm³"], "tip": "Cross-section × length."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["25.1", "8π", "25.13"], ["62.8", "20π", "62.83"], ["88.0", "88", "87.96", "28π"]], "tips": ["Two circles + curved surface."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["5.65", "5.7", "1.8π", "curved"], ["1.13", "0.36π", "6.78", "6.8"], ["4"]], "tips": ["Curved + top, then ÷ 2, round up."]}]}, "models": {"1": [["Q1", "31.4 cm; 78.5 cm²; 18.8 cm; π × 9 = 28.3 cm²."]], "2": [["Q2", "Square = 64 cm² [1]; semicircle = ½ × π × 4² = 25.1 cm² [1]; total = 89.1 cm² [1]."], ["Q3", "1000 cm³; 10 000 cm²; 0.25 m; 2.5 × 1 000 000 cm³."]], "3": [["Q4", "r = 0.6 m [1]; V = π × 0.6² × 1.5 ≈ 1.70 m³ [1] ≈ 1696 litres (about 1700 litres) [1]."], ["Q5", "120 cm³; 282.7 cm³; 240 cm³."]], "4": [["Q6", "Two circles = 2 × π × 2² = 25.1 cm² [1]; curved surface = 2π × 2 × 5 = 62.8 cm² [1]; total = 88.0 cm² [1]."]], "5": [["Q7", "Curved surface = 2π × 0.6 × 1.5 ≈ 5.65 m² [1]; top = π × 0.6² ≈ 1.13 m², total ≈ 6.78 m² [1]; 6.78 ÷ 2 = 3.39, so 4 tins are needed (round up) [1]."]], "6": [["Exit ticket", "V = πr²h."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q4", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Calculate (to 1 d.p., π = 3.142).", "Q2": "A shape is a square of side 8 cm with a semicircle of diameter 8 cm attached to one side. Calculate its area to 1 decimal place.", "Q3": "Convert.", "Q4": "A cylindrical tank has a diameter of 1.2 m and a height of 1.5 m. Calculate its volume in m³ and in litres (1 m³ = 1000 litres).", "Q5": "Volume.", "Q6": "Calculate the total surface area of a cylinder with radius 2 cm and height 5 cm, to 1 decimal place.", "Q7": "The curved side and top of the tank (r = 0.6 m, h = 1.5 m) are painted. One tin covers 2 m². How many tins are needed?"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
