insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-MATHS-L9', 'Unit 9 Angles, polygons, Pythagoras and constructions: Angles, polygons and Pythagoras'' theorem', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["540°", "720°", "72°", "108°", "30°"], "tip": "(n − 2) × 180; 360 ÷ n."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["360 ÷ 24", "360/24"], ["15"]], "tips": ["360 ÷ exterior."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Alternate angles", "Corresponding angles", "Co-interior angles", "Angles on a straight line"], "tip": "Z, F, C."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["115"], ["co-interior", "180"]], "tips": ["Add to 180."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 4, "n": 4, "ans": ["5", "13", "12", "10"], "tip": "Square, add or subtract, root."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["9 + 16", "25", "3² + 4²"], ["5"]], "tips": ["Ladder is the hypotenuse."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 4, "n": 4, "ans": ["3", "9", "Infinitely many", "4"], "tip": "Visualise the cuts."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 3, "pts": [["6400 + 3600", "10000", "80² + 60²"], ["100"], ["rectangle", "90", "right angle"]], "tips": ["The diagonal is the hypotenuse."]}]}, "models": {"1": [["Q1", "540°; 720°; 72°; 108°; 30°."], ["Q2", "n = 360 ÷ 24 [1] = 15 sides [1]."]], "2": [["Q3", "Z: alternate; F: corresponding; C: co-interior; straight line: 180°."], ["Q4", "115° [1] because co-interior angles add up to 180° [1]."]], "3": [["Q5", "5; 13; 12; 10."], ["Q6", "c² = 3² + 4² = 9 + 16 = 25 [1], so the ladder is 5 m [1]."]], "4": [["Q7", "Cuboid 3; cube 9; cylinder infinitely many; square-based pyramid 4 (two through opposite edges, two through the midpoints of opposite sides)."], ["Q8", "Draw a line; arc from one end; arc of the same radius from the crossing point; join: 60°. Bisect with equal arcs from both arms."]], "5": [["Q9", "d² = 80² + 60² = 6400 + 3600 = 10 000 [1]; d = 100 cm [1]; the triangle is right-angled because the corners of a rectangle are 90° [1]."]], "6": [["Exit ticket", "In a right-angled triangle, a² + b² = c², where c is the hypotenuse."]]}, "labels": {"q1_1": "Q2", "q2_1": "Q4", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Calculate.", "Q2": "A regular polygon has exterior angles of 24°. How many sides does it have?", "Q3": "Name the angle fact.", "Q4": "Two parallel lines are crossed by a transversal. One angle is 65°. Find the co-interior angle and give a reason.", "Q5": "Find the missing side.", "Q6": "A ladder stands 3 m from a wall and reaches 4 m up it. How long is the ladder? Show your working.", "Q7": "How many planes of symmetry?", "Q8": "In your book, use a ruler and compasses to construct a 60° angle, then bisect it to make 30°. Describe your steps.", "Q9": "A rectangular TV screen is 80 cm wide and 60 cm tall. Calculate the length of its diagonal, and say why the triangle formed is right-angled."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.quizzes (id, topic_id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by) values ('ef719117-a5cd-5df5-96ba-bcb2b64d6b2c', '1d5609c9-6a9d-57ab-bbfd-eca519b0320d', 'Stage 9 Mathematics · Unit 9 Angles, polygons, Pythagoras and constructions · Checkpoint-style questions', 'Checkpoint-style questions for Stage 9 Mathematics, Unit 9 Angles, polygons, Pythagoras and constructions (objectives 9Gg.06, 9Gg.07, 9Gg.08, 9Gg.09, 9Gg.10, 9Gg.11), written in the style of the Cambridge Lower Secondary Checkpoint papers. 9 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark.', null, 2, true, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, topic_id = excluded.topic_id;
