insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('d4a4d6e2-89ab-5e48-96a2-98d7332c4550', '29704b66-9095-5ad7-9720-38fa4da52d7e', 'Unit 10 Bearings and transformations: Bearings, maps and transformations', 'Stage 9 Mathematics · Objectives 9Gp.01, 9Gp.02, 9Gp.03, 9Gp.04, 9Gp.05, 9Gp.06, 9Gp.07', '/cks9-maths-10/', 'CKS9-MATHS-L10', 21, 60, 100) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-MATHS-L10', 'Unit 10 Bearings and transformations: Bearings, maps and transformations', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["090°", "180°", "270°", "045°", "245°"], "tip": "Clockwise from north."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["(4, 6)", "(1, −1)", "7 km", "1.5 km"], "tip": "Average the coordinates."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Reflection", "Translation", "Rotation", "Enlargement"], "tip": "Flip, turn, slide or resize."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["reflect"], ["y-axis", "x = 0", "x=0"]], "tips": ["What changed sign?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["36"], ["80"], ["4 times", "× 4", "x 4", "squared", "k²", "four times"]], "tips": ["Lengths × 2, area × 4."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["36 + 64", "100", "6² + 8²"], ["10"], ["217", "216", "217°"]], "tips": ["Pythagoras, then bearing."]}]}, "models": {"1": [["Q1", "090°; 180°; 270°; 045°; 065° + 180° = 245°."]], "2": [["Q2", "(4, 6); (1, −1); 7 km; 3 × 500 m = 1.5 km."]], "3": [["Q3", "Flip: reflection; slide: translation; turn: rotation; resize: enlargement."], ["Q4", "A reflection [1] in the y-axis (the line x = 0) [1]."]], "4": [["Q5", "New rectangle 8 cm by 10 cm, perimeter = 36 cm [1]; area = 80 cm² [1]; the area is 4 times larger because area scales by k² = 2² [1]."]], "5": [["Q6", "Distance² = 6² + 8² = 100 [1], so it is 10 km from the start [1]; from the boat the start is south-west: 180° + 37° = 217° [1]."]], "6": [["Exit ticket", "300°."]]}, "labels": {"q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Write the bearing.", "Q2": "Calculate.", "Q3": "Which transformation?", "Q4": "Describe fully the single transformation that maps a triangle with vertices (1, 1), (3, 1), (1, 2) onto (−1, 1), (−3, 1), (−1, 2).", "Q5": "A rectangle 4 cm by 5 cm is enlarged by scale factor 2. Find the new perimeter and area, and explain how the area changes.", "Q6": "A boat sails 6 km due east, then 8 km due north. How far is it from the start, and what is the bearing of the start from the boat''s final position? (Use Pythagoras; the angle at the boat is about 37° west of south.)"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
