insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('f3811c43-1081-55f1-907c-69f0febcd833', '52974a02-57d0-5f25-9f11-354229ef06c7', 'Unit 11 Statistics: Statistical investigations', 'Stage 9 Mathematics · Objectives 9Ss.01, 9Ss.02, 9Ss.03, 9Ss.04, 9Ss.05', '/cks9-maths-11/', 'CKS9-MATHS-L11', 19, 60, 110) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-MATHS-L11', 'Unit 11 Statistics: Statistical investigations', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Biased", "Fair", "Biased", "Biased"], "tip": "Does everyone have a fair chance?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Pie or bar chart", "Frequency diagram (grouped)", "Scatter graph", "Frequency diagram (grouped)"], "tip": "Type of data?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["145", "155", "midpoint", "3200"], ["160"], ["150–160", "150-160", "150 to 160"]], "tips": ["Midpoints × frequency."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["x+higher", "x scored more", "x better on average"], ["y+consistent", "y less spread", "y smaller range"]], "tips": ["Average AND spread, in context."]}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["not start", "not zero", "0", "broken"], ["exaggerat", "looks bigger", "difference", "small difference"]], "tips": ["Where does the axis start?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["random", "sample"], ["hours", "sleep", "score"], ["scatter"], ["large", "bias", "all classes", "anonymous", "not just friends"]], "tips": ["Sample, data, graph, fairness."]}]}, "models": {"1": [["Q1", "Only the random list is fair; the others select particular groups or lead the answer."]], "2": [["Q2", "Categorical: bar/pie. Continuous: grouped frequency diagram. Two variables: scatter."]], "3": [["Q3", "Midpoints 145, 155, 165, 175: Σfx = 435 + 1240 + 825 + 700 = 3200 [1]; mean ≈ 3200 ÷ 20 = 160 cm [1]; modal class 150–160 cm [1]."]], "4": [["Q4", "Team X scored more points on average (higher mean) [1]; Team Y was more consistent because its range is smaller [1]."], ["Q5", "The vertical axis does not start at 0 [1], so a small difference between the values looks much bigger than it really is [1]."]], "5": [["Q6", "Choose a random sample of, say, 40 Year 9 students [1]; record each student''s hours of sleep and test score [1]; plot a scatter graph to look for correlation [1]; avoid bias by using a large sample from all classes (not just friends) and anonymous questions [1]."]], "6": [["Exit ticket", "A sample that does not fairly represent the population, so some groups are more or less likely to be chosen."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Biased or fair?", "Q2": "Best graph?", "Q3": "Heights (cm): 140–150: 3 students; 150–160: 8; 160–170: 5; 170–180: 4. Estimate the mean height and state the modal class.", "Q4": "Team X: mean 14 points, range 20. Team Y: mean 12 points, range 6. Compare the two teams.", "Q5": "A bar chart''s vertical axis starts at 90 instead of 0, so one bar looks five times taller than another. Explain why the graph is misleading.", "Q6": "Plan an investigation into whether Year 9 students who sleep more get higher test scores. Describe the sample, the data, the graph and how you would avoid bias."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
