insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-MATHS-L12', 'Unit 12 Probability: Combined events and probability', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["0.7", "0.35", "0.15", "5/8"], "tip": "Subtract from 1."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["1/36", "1/6", "1/12", "1/2"], "tip": "Count in the 36-square grid."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Independent", "Not independent", "Independent", "Independent"], "tip": "Does the first change the second?"}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 3, "pts": [["9/25", "0.36"], ["6/25", "3/5 × 2/5", "0.24"], ["12/25", "0.48"]], "tips": ["Multiply along, add branches."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["50"], ["74", "more", "higher"], ["biased", "unfair", "not fair"]], "tips": ["Expected = 0.25 × 200."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["no", "not definitely", "not certain", "wrong"], ["1/36", "each roll", "independent", "chance"], ["10"]], "tips": ["Expected is not guaranteed."]}]}, "models": {"1": [["Q1", "0.7; 0.35; 0.15; 5/8."]], "2": [["Q2", "1/36; 6/36 = 1/6; 3/36 = 1/12; 18/36 = 1/2."]], "3": [["Q3", "Only removing without replacement changes the second probability."], ["Q4", "P(both red) = 3/5 × 3/5 = 9/25 [1]; P(red then blue) = 3/5 × 2/5 = 6/25, and blue then red is also 6/25 [1]; so P(one of each) = 12/25 [1]."]], "4": [["Q5", "Expected red = 0.25 × 200 = 50 [1]; observed 74 is much higher than expected [1]; after 200 spins this suggests the spinner is biased towards red [1]."]], "5": [["Q6", "No, he is not right [1]; each roll is independent with probability 1/36, so a double six is likely but not certain in 36 rolls [1]; in 360 rolls he should expect about 360 × 1/36 = 10 double sixes [1]."]], "6": [["Exit ticket", "0.2."]]}, "labels": {"q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Find the missing probability.", "Q2": "Two fair dice are rolled.", "Q3": "Independent?", "Q4": "A bag has 3 red and 2 blue balls. A ball is taken, replaced, and a second ball is taken. Find P(both red) and P(one red and one blue).", "Q5": "A spinner is spun 200 times and lands on red 74 times. The theoretical probability of red is 0.25. Compare the expected and observed results and suggest a conclusion.", "Q6": "Malik says: \"There are 36 outcomes, so if I roll two dice 36 times I will definitely get a double six.\" Is he right? Use probability to explain, and say how many double sixes he should expect in 360 rolls."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
