insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('57cdde9f-e2e0-5306-bf7c-f513c841a1c8', 'a4dc81b0-3ded-5ab3-b73e-f8636c4c63e4', 'short', 'P(Ali wins) = 0.6 and P(Ben wins) = 0.3 in two separate, independent games. Find the probability that both win.', '[]'::jsonb, 2, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
