insert into public.questions (id, kind, prompt, options, marks, section, created_by) values ('5e3ba0d9-4631-5b01-8ea8-77e1e346e712', 'short', '3. A farmer''s crop has yellow leaves. Tests show the soil lacks magnesium. Explain why the crop grows poorly.', '[]'::jsonb, 3, 'Paper 1', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5e3ba0d9-4631-5b01-8ea8-77e1e346e712', 'Magnesium is needed to make chlorophyll [1]; with less chlorophyll less light is absorbed for photosynthesis [1], so less glucose is made for growth [1].', 'Magnesium is needed to make chlorophyll [1]; with less chlorophyll less light is absorbed for photosynthesis [1], so less glucose is made for growth [1].', '[{"text": "Magnesium is needed to make chlorophyll", "any": ["chlorophyll"], "all": [], "marks": 1}, {"text": "With less chlorophyll less light is absorbed for photosynthesis", "any": ["light", "photosynthesis"], "all": [], "marks": 1}, {"text": "Less glucose is made for growth", "any": ["glucose", "food", "sugar"], "all": [], "marks": 1}]'::jsonb, 'Magnesium is needed to make chlorophyll [1]; with less chlorophyll less light is absorbed for photosynthesis [1], so less glucose is made for growth [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
