insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e0fcee9b-d847-57bc-96c0-678a092b993a', '24 ÷ 8 = 3 mm per minute [1]; e.g. use a fan, raise the temperature or increase the light [1].', '24 ÷ 8 = 3 mm per minute [1]; e.g. use a fan, raise the temperature or increase the light [1].', '[{"text": "24 ÷ 8 = 3 mm per minute", "any": ["3"], "all": [], "marks": 1}, {"text": "E.g. use a fan, raise the temperature or increase the light", "any": ["wind", "fan", "warm", "heat", "light", "dry"], "all": [], "marks": 1}]'::jsonb, '24 ÷ 8 = 3 mm per minute [1]; e.g. use a fan, raise the temperature or increase the light [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
