insert into public.questions (id, kind, prompt, options, marks, section, created_by) values ('59bff31d-da19-5db1-bac5-51b9be413cc2', 'short', '7. A human egg cell has 23 chromosomes. State how many chromosomes are in a sperm cell and in a fertilised egg, and explain.', '[]'::jsonb, 3, 'Paper 1', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('59bff31d-da19-5db1-bac5-51b9be413cc2', 'A sperm cell has 23 [1] and a fertilised egg has 46 [1] because the nuclei of the two gametes, each with half the chromosomes, fuse [1].', 'A sperm cell has 23 [1] and a fertilised egg has 46 [1] because the nuclei of the two gametes, each with half the chromosomes, fuse [1].', '[{"text": "A sperm cell has 23", "any": ["23"], "all": [], "marks": 1}, {"text": "A fertilised egg has 46", "any": ["46"], "all": [], "marks": 1}, {"text": "Because the nuclei of the two gametes, each with half the chromosomes, fuse", "any": ["fuse", "join", "half", "one from each"], "all": [], "marks": 1}]'::jsonb, 'A sperm cell has 23 [1] and a fertilised egg has 46 [1] because the nuclei of the two gametes, each with half the chromosomes, fuse [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
