insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5ab210ca-f4e9-5b0c-8ae9-a2eca2de2910', 'Half of the father''s sperm carry an X chromosome and half carry a Y [1]; an egg (X) fertilised by a Y sperm gives XY, a boy [1].', 'Half of the father''s sperm carry an X chromosome and half carry a Y [1]; an egg (X) fertilised by a Y sperm gives XY, a boy [1].', '[{"text": "Half of the father''s sperm carry an X chromosome and half carry a Y", "any": ["x or y", "half carry y"], "all": [], "marks": 1}, {"text": "An egg (X) fertilised by a Y sperm gives XY, a boy", "any": ["xy"], "all": [], "marks": 1}]'::jsonb, 'Half of the father''s sperm carry an X chromosome and half carry a Y [1]; an egg (X) fertilised by a Y sperm gives XY, a boy [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
