insert into public.questions (id, kind, prompt, options, marks, section, created_by) values ('5f73f5f8-4b30-5926-8c55-7281cc8b455f', 'short', '10. Bacteria in a population vary. Some are resistant to an antibiotic. Use natural selection to explain how a population of resistant bacteria develops.', '[]'::jsonb, 4, 'Paper 1', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5f73f5f8-4b30-5926-8c55-7281cc8b455f', 'The bacteria vary and some are resistant [1]; the antibiotic kills the non-resistant bacteria [1]; the resistant ones survive [1] and reproduce, passing on the resistance gene, so the population becomes resistant [1].', 'The bacteria vary and some are resistant [1]; the antibiotic kills the non-resistant bacteria [1]; the resistant ones survive [1] and reproduce, passing on the resistance gene, so the population becomes resistant [1].', '[{"text": "The bacteria vary and some are resistant", "any": ["vary", "some resistant", "variation"], "all": [], "marks": 1}, {"text": "The antibiotic kills the non-resistant bacteria", "any": ["killed", "die", "non-resistant"], "all": [], "marks": 1}, {"text": "The resistant ones survive", "any": ["survive"], "all": [], "marks": 1}, {"text": "Reproduce, passing on the resistance gene, so the population becomes resistant", "any": ["reproduce", "multiply", "pass on"], "all": [], "marks": 1}]'::jsonb, 'The bacteria vary and some are resistant [1]; the antibiotic kills the non-resistant bacteria [1]; the resistant ones survive [1] and reproduce, passing on the resistance gene, so the population becomes resistant [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
