insert into public.questions (id, kind, prompt, options, marks, section, created_by) values ('c3c62687-0881-5b7e-b546-23c3996d4d9a', 'short', '11. Describe how to make pure, dry crystals of copper sulfate from copper carbonate and dilute sulfuric acid.', '[]'::jsonb, 4, 'Paper 1', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c3c62687-0881-5b7e-b546-23c3996d4d9a', 'Add copper carbonate to the acid until it is in excess [1]; filter off the unreacted carbonate [1]; heat the filtrate to evaporate some water [1]; leave to cool so crystals form, then dry them [1].', 'Add copper carbonate to the acid until it is in excess [1]; filter off the unreacted carbonate [1]; heat the filtrate to evaporate some water [1]; leave to cool so crystals form, then dry them [1].', '[{"text": "Add copper carbonate to the acid until it is in excess", "any": ["excess"], "all": [], "marks": 1}, {"text": "Filter off the unreacted carbonate", "any": ["filter"], "all": [], "marks": 1}, {"text": "Heat the filtrate to evaporate some water", "any": ["evaporat", "heat"], "all": [], "marks": 1}, {"text": "Leave to cool so crystals form, then dry them", "any": ["cool", "crystal", "dry"], "all": [], "marks": 1}]'::jsonb, 'Add copper carbonate to the acid until it is in excess [1]; filter off the unreacted carbonate [1]; heat the filtrate to evaporate some water [1]; leave to cool so crystals form, then dry them [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
