insert into public.questions (id, kind, prompt, options, marks, section, created_by) values ('7e24f555-2a1e-5834-ac33-292d816945f2', 'short', '6. Explain how evaporation of sweat cools the skin.', '[]'::jsonb, 3, 'Paper 1', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7e24f555-2a1e-5834-ac33-292d816945f2', 'Sweat evaporates [1]; the particles with the most energy escape [1], so the average energy of those left falls and the skin cools [1].', 'Sweat evaporates [1]; the particles with the most energy escape [1], so the average energy of those left falls and the skin cools [1].', '[{"text": "Sweat evaporates", "any": ["evaporat"], "all": [], "marks": 1}, {"text": "The particles with the most energy escape", "any": ["most energy", "energetic", "fastest", "escape"], "all": [], "marks": 1}, {"text": "The average energy of those left falls and the skin cools", "any": ["lower", "average", "cooler"], "all": [], "marks": 1}]'::jsonb, 'Sweat evaporates [1]; the particles with the most energy escape [1], so the average energy of those left falls and the skin cools [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
